(window.ONTHI_DOCS=window.ONTHI_DOCS||[]).push({"id":"hn4-15-25","name":"Hán ngữ quyển 4 · Bài 15–25","builtin":true,"lessons":[{"n":15,"zh":"会议厅的门开着呢","vi":"Cửa hội trường đang mở","texts":[{"zh":"（一）会议厅的门开着呢","vi":"Cửa hội trường đang mở","phu":false,"pairs":[["玛丽：请问，刚才进去一位女士，你看见没有？","Mary: Xin hỏi, vừa rồi có một quý cô đi vào, anh có thấy không?"],["服务员：什么女士？长得什么样？","Phục vụ: Quý cô nào? Trông thế nào?"],["玛丽：她个子高高的，大概有一米七左右，黄头发，大眼睛，戴着一副眼镜儿。上身穿着一件红色的西服，下边穿着一条黑色的裙子。","Mary: Cô ấy dáng cao cao, khoảng chừng một mét bảy, tóc vàng, mắt to, đeo một cặp kính. Bên trên mặc một chiếc áo vest màu đỏ, bên dưới mặc một chiếc váy màu đen."],["服务员：是干什么的？","Phục vụ: Cô ấy làm nghề gì?"],["玛丽：是电视台的主持人。","Mary: Là người dẫn chương trình của đài truyền hình."],["服务员：后边是不是还跟着两个小伙子，扛着摄像机？","Phục vụ: Phía sau có phải còn có hai chàng trai đi theo, vác máy quay không?"],["玛丽：对。","Mary: Đúng."],["服务员：会议厅的门开着呢，你们进去找吧。","Phục vụ: Cửa hội trường đang mở, các bạn vào tìm đi."],["玛丽：里边正开着会吗？","Mary: Bên trong đang họp à?"],["服务员：没有。你们看，是不是手里拿着麦克风，对着摄像机讲话的那位？","Phục vụ: Không. Các bạn xem, có phải là người tay cầm micro, đang nói trước máy quay kia không?"],["玛丽：对，就是她。他们正等着我们呢。","Mary: Đúng, chính là cô ấy. Họ đang đợi chúng tôi."],["服务员：你们进去吧。","Phục vụ: Các bạn vào đi."],["玛丽：谢谢啦！","Mary: Cảm ơn nhé!"],["服务员：不客气。","Phục vụ: Không có gì."]]},{"zh":"（二）墙上贴着红双喜字","vi":"Trên tường dán chữ song hỷ đỏ","phu":false,"pairs":[["玛丽：你昨天去哪儿了？","Mary: Hôm qua cậu đi đâu thế?"],["麦克：张东带我去参加了一个中国人的婚礼。","Mike: Trương Đông dẫn mình đi dự đám cưới của một người Trung Quốc."],["玛丽：怎么样？听说中国人的婚礼很热闹。","Mary: Thế nào? Nghe nói đám cưới của người Trung Quốc rất náo nhiệt."],["麦克：是！我是第一次参加这样的婚礼。屋子里挂着大红灯笼，墙上贴着一个很大的红双喜字。桌子上摆着很多酒和菜。新娘长得很漂亮，穿着一件红棉袄，头上还戴着红花。新郎是一个帅小伙儿，穿着一身深蓝色的西服，系着红领带。他们笑着对我们说：“欢迎！欢迎！”新娘热情地请客人吃糖，新郎忙着给客人倒喜酒。孩子们不停地说着、笑着，热热闹闹的，气氛非常好。","Mike: Đúng vậy! Đây là lần đầu mình dự một đám cưới như thế. Trong phòng treo đèn lồng đỏ, trên tường dán một chữ song hỷ đỏ rất to. Trên bàn bày rất nhiều rượu và thức ăn. Cô dâu rất xinh, mặc một chiếc áo bông đỏ, trên đầu còn cài hoa đỏ. Chú rể là một chàng trai đẹp trai, mặc một bộ âu phục màu xanh đậm, thắt cà vạt đỏ. Họ cười nói với chúng mình: “Hoan nghênh! Hoan nghênh!” Cô dâu nhiệt tình mời khách ăn kẹo, chú rể bận rót rượu mừng cho khách. Bọn trẻ cứ nói nói cười cười không ngớt, rộn ràng náo nhiệt, không khí vô cùng vui vẻ."],["玛丽：“喜酒”是什么酒？","Mary: “Rượu mừng” là rượu gì?"],["麦克：结婚时喝的酒中国人叫喜酒，吃的糖叫喜糖。所以，中国人要问“什么时候吃你的喜糖啊”，就是问你什么时候结婚。","Mike: Rượu uống khi cưới người Trung Quốc gọi là rượu mừng, kẹo ăn gọi là kẹo mừng. Vì vậy, người Trung Quốc mà hỏi “Bao giờ được ăn kẹo mừng của bạn?” tức là hỏi bạn khi nào kết hôn."],["玛丽：是吗？","Mary: Thế à?"]]},{"zh":"（综合填空）王老师出院了","vi":"Thầy Vương ra viện rồi","phu":true,"pairs":[["王老师已经好几天没有给我们上课了，因为他生病住院了。老师住院以后，我们班的学生都去医院看过他。我们都希望老师能早点儿好，因为我们觉得他是个好老师，对我们就像对自己的儿女一样。","Thầy Vương đã mấy ngày không lên lớp dạy chúng tôi, vì thầy bị bệnh phải nằm viện. Sau khi thầy nằm viện, sinh viên lớp tôi đều đã đến bệnh viện thăm thầy. Chúng tôi đều mong thầy sớm khỏe, vì chúng tôi thấy thầy là một người thầy tốt, đối với chúng tôi như đối với con cái của mình vậy."],["今天早上，我刚走进教室，就看见王老师在讲台旁边站着。我高兴地向老师问了一声好。我问：“老师，您什么时候出院的？”","Sáng nay, tôi vừa bước vào lớp đã thấy thầy Vương đang đứng cạnh bục giảng. Tôi vui vẻ chào thầy một tiếng. Tôi hỏi: “Thầy ơi, thầy ra viện lúc nào vậy ạ?”"],["“我前天出的院。听说你也病了，好了吗？”“好了。老师，您要保重身体！”“谢谢你！”","“Thầy ra viện hôm kia. Nghe nói em cũng bị ốm, khỏi chưa?” “Em khỏi rồi ạ. Thầy phải giữ gìn sức khỏe nhé!” “Cảm ơn em!”"],["这时，同学们都走进教室来了，大家看到王老师又能给我们上课了，都很高兴。老师也高兴地和大家说着话，问每个同学的情况。我们都知道王老师刚出院，身体还不太好。","Lúc này, các bạn đều bước vào lớp, mọi người thấy thầy Vương lại có thể dạy chúng tôi, ai cũng rất vui. Thầy cũng vui vẻ trò chuyện với mọi người, hỏi han tình hình từng bạn. Chúng tôi đều biết thầy Vương vừa ra viện, sức khỏe còn chưa tốt lắm."],["上课铃响了。大家一起大声地说：“老师好！”王老师笑着点了点头，也对我们说：“同学们好！”","Chuông vào lớp reo. Mọi người đồng thanh nói to: “Chúng em chào thầy ạ!” Thầy Vương mỉm cười gật đầu, cũng nói với chúng tôi: “Chào các em!”"],["老师拿起书要开始讲课了。山本搬了一把椅子，走到老师面前，说：“老师，今天请您坐着讲吧。”王老师说：“谢谢，我不累，我不习惯坐着上课。”王老师没有坐。","Thầy cầm sách lên chuẩn bị giảng bài. Yamamoto bê một cái ghế đến trước mặt thầy, nói: “Thầy ơi, hôm nay mời thầy ngồi giảng ạ.” Thầy Vương nói: “Cảm ơn em, thầy không mệt, thầy không quen ngồi dạy.” Thầy Vương không ngồi."],["“老师，请您坐下讲吧！”这时，班长带着全班同学一起大声地说。王老师有点儿激动地看着我们说：“谢谢大家！谢谢同学们！”","“Thầy ơi, mời thầy ngồi xuống giảng ạ!” Lúc này, lớp trưởng dẫn cả lớp cùng nói to. Thầy Vương hơi xúc động nhìn chúng tôi nói: “Cảm ơn mọi người! Cảm ơn các em!”"]]}],"grammar":[{"title":"Động từ + 着 — động tác/trạng thái đang kéo dài","f":["Khẳng định: Chủ ngữ + Động từ + 着 (+ tân ngữ) (+ 呢)","Phủ định: 没(有) + Động từ + 着","Câu hỏi: Động từ + 着 (+ tân ngữ) + 没有？"],"note":"着 diễn tả một trạng thái đang được giữ nguyên (cửa đang mở, đèn đang bật, đang mặc áo…). Phủ định dùng 没, không dùng 不, và bỏ 呢.","ex":[["会议厅的门开着呢。","Cửa hội trường đang mở."],["她穿着一件红毛衣，戴着一副眼镜儿。","Cô ấy mặc áo len đỏ, đeo một cặp kính."],["窗户没开着。","Cửa sổ không mở."],["电视开着没有？","Ti vi có đang bật không?"]],"warn":["Sau 着 không dùng 了 hay 过: 门开着了 là sai.","Hay đi với 正 / 正在 / 在 / 呢: 他们正等着我们呢。","Chỉ nơi chốn sau động từ thì dùng 在, không dùng 着: *他躺着床上* → 他躺在床上."]},{"title":"V1 + 着 + V2 — làm V2 trong trạng thái V1","f":["Chủ ngữ + Động từ 1 + 着 (+ tân ngữ) + Động từ 2"],"note":"V1着 chỉ cách thức hoặc tư thế khi làm V2: cười mà nói, đi bộ mà đến, cầm hoa mà vào…","ex":[["她笑着对我说：“欢迎！欢迎！”","Cô ấy cười nói với tôi: “Chào mừng!”"],["我们走着去吧。","Mình đi bộ đi."],["他拿着一束花走进来了。","Anh ấy cầm một bó hoa đi vào."]],"warn":[]}]},{"n":16,"zh":"前边开过来一辆空车","vi":"Phía trước có một chiếc xe trống chạy tới","texts":[{"zh":"（一）前边开过来一辆空车","vi":"Phía trước có một chiếc xe trống chạy tới","phu":false,"pairs":[["田芳：等车的人越来越多了，咱们还是打的去吧，别坐公共汽车了。","Điền Phương: Người chờ xe càng ngày càng đông, chúng ta vẫn nên đi taxi thôi, đừng đi xe buýt nữa."],["玛丽：好吧，你看，那边正好开过来一辆空车，就坐这辆吧。","Mary: Được, cậu xem, đằng kia vừa đúng lúc có một chiếc xe trống chạy tới, đi xe này luôn đi."],["玛丽：你家住的是四合院儿吗？","Mary: Nhà cậu ở là nhà tứ hợp à?"],["田芳：是啊。我家院子里种着一棵大枣树，树上结着很多红枣，远远儿地就能看见。一看见那棵大枣树就看到我家了。今天请你们尝尝我家的红枣，可甜了。","Điền Phương: Đúng vậy. Trong sân nhà mình trồng một cây táo lớn, trên cây ra rất nhiều táo đỏ, từ xa đã nhìn thấy. Hễ thấy cây táo lớn đó là thấy nhà mình rồi. Hôm nay mời các cậu nếm thử táo đỏ nhà mình, ngọt lắm."],["玛丽：我听说现在住四合院儿的越来越少了。","Mary: Mình nghe nói bây giờ người ở nhà tứ hợp càng ngày càng ít."],["田芳：是。现在城市里大楼越盖越多，住宅小区也越建越漂亮。很多人都搬进楼房里去住了。我们院子里最近也搬走了五六家，明年我们家也要搬走了。","Điền Phương: Đúng. Bây giờ nhà cao tầng trong thành phố xây càng lúc càng nhiều, khu dân cư cũng xây càng lúc càng đẹp. Rất nhiều người đã chuyển vào ở nhà lầu. Sân nhà mình gần đây cũng có năm, sáu nhà chuyển đi, sang năm nhà mình cũng sắp chuyển rồi."],["玛丽：那太遗憾了。","Mary: Thế thì tiếc quá."],["田芳：我虽然也舍不得离开我们家的小院儿，但还是希望快点儿搬进现代化的楼房里去住。","Điền Phương: Tuy mình cũng không nỡ rời xa cái sân nhỏ của nhà mình, nhưng vẫn mong sớm được chuyển vào ở nhà lầu hiện đại."]]},{"zh":"（二）年轻人打扮得越来越漂亮了","vi":"Người trẻ ăn diện ngày càng đẹp","phu":false,"pairs":[["王老师：同学们已经学了两个多月汉语了。今天，想请大家随便谈谈自己的感想和体会，有什么意见和建议也可以提。","Thầy Vương: Các em đã học tiếng Hán hơn hai tháng rồi. Hôm nay, thầy muốn mời mọi người tự do nói về cảm tưởng và trải nghiệm của mình, có ý kiến và đề nghị gì cũng có thể nêu ra."],["玛丽：刚来的时候，我不习惯北京的气候，常常感冒，现在越来越习惯了。","Mary: Lúc mới đến, em không quen khí hậu Bắc Kinh, thường xuyên bị cảm, bây giờ càng ngày càng quen rồi."],["麦克：我们的汉语越来越好，觉得越学越有意思了。","Mike: Tiếng Hán của chúng em càng ngày càng tốt, cảm thấy càng học càng thú vị."],["玛丽：我的朋友越来越多了。","Mary: Bạn bè của em càng ngày càng nhiều."],["麦克：朋友越多越好，“在家靠父母，出门靠朋友”嘛。","Mike: Bạn bè càng nhiều càng tốt, vì “ở nhà nhờ cha mẹ, ra ngoài nhờ bạn bè” mà."],["山本：中国菜很好吃，我越吃越喜欢，所以也越来越胖了。","Yamamoto: Món Trung Quốc rất ngon, em càng ăn càng thích, nên cũng càng ngày càng béo."],["麦克：我觉得人们的生活一天比一天丰富，年轻人越来越会打扮，打扮得越来越漂亮了。","Mike: Em thấy cuộc sống của mọi người ngày một phong phú, người trẻ càng ngày càng biết ăn diện, ăn mặc ngày càng đẹp."],["玛丽：圣诞节和新年快到了，不少商店都摆着圣诞树，装饰得非常漂亮，我看见很多中国人也买圣诞树和圣诞礼物。","Mary: Giáng sinh và năm mới sắp đến rồi, nhiều cửa hàng bày cây thông Noel, trang trí rất đẹp, em thấy nhiều người Trung Quốc cũng mua cây thông và quà Giáng sinh."],["麦克：老师，我听说中国过圣诞节的人越来越多了，是吗？","Mike: Thưa thầy, em nghe nói ở Trung Quốc người đón Giáng sinh ngày càng nhiều, phải không ạ?"],["王老师：一般家庭是不过圣诞节的。有的人过圣诞节，可能是喜欢圣诞节那种欢乐的气氛，孩子们能从爸爸妈妈那儿得到礼物，当然也很高兴。不过，中国最大的节日还是春节。","Thầy Vương: Các gia đình thông thường không đón Giáng sinh. Có người đón Giáng sinh có lẽ vì thích bầu không khí vui vẻ đó, trẻ con được bố mẹ tặng quà, đương nhiên cũng rất vui. Nhưng ngày lễ lớn nhất của Trung Quốc vẫn là Tết Nguyên đán."],["麦克：老师，我建议，咱们开一个新年联欢会，怎么样？","Mike: Thưa thầy, em đề nghị chúng ta tổ chức một buổi liên hoan năm mới, thầy thấy sao ạ?"],["王老师：好啊！","Thầy Vương: Hay đấy!"]]},{"zh":"（综合填空）到田芳家做客","vi":"Đến nhà Điền Phương làm khách","phu":true,"pairs":[["昨天我们到田芳家去做客。去的时候，雨下得很大，不过我们一到田芳家雨就停了。","Hôm qua chúng tôi đến nhà Điền Phương làm khách. Lúc đi, mưa rất to, nhưng chúng tôi vừa đến nhà Điền Phương thì mưa tạnh."],["田芳家住在一个四合院儿里。院子里种着一棵枣树，还种着很多花儿，有红的，有黄的，非常漂亮。他们家的院子不太大，但是很干净，也很安静。","Nhà Điền Phương ở trong một khu tứ hợp viện. Trong sân trồng một cây táo, còn trồng rất nhiều hoa, có hoa đỏ, có hoa vàng, vô cùng đẹp. Sân nhà họ không lớn lắm nhưng rất sạch sẽ, cũng rất yên tĩnh."],["田芳的爸爸妈妈一看我们来了，就走出来笑着说：“欢迎你们来我家做客，请到屋里坐吧。”田芳给我们介绍了她的爸爸妈妈。","Bố mẹ Điền Phương vừa thấy chúng tôi đến liền đi ra cười nói: “Chào mừng các cháu đến nhà chơi, mời vào nhà ngồi.” Điền Phương giới thiệu bố mẹ cô ấy với chúng tôi."],["我知道田芳的爸爸妈妈都是大学教授。田芳的爸爸说：“你们就叫我们田老师和黄老师吧。”黄老师热情地给我们倒茶，请我们吃水果。她说：“你们跟田芳是同学，又是好朋友，到这儿来就像到自己家里一样，不要客气。”","Tôi biết bố mẹ Điền Phương đều là giáo sư đại học. Bố Điền Phương nói: “Các cháu cứ gọi chúng tôi là thầy Điền và cô Hoàng nhé.” Cô Hoàng nhiệt tình rót trà cho chúng tôi, mời chúng tôi ăn hoa quả. Cô nói: “Các cháu là bạn học, lại là bạn thân của Điền Phương, đến đây cứ như ở nhà mình, đừng khách sáo.”"],["田芳说：“先参观参观我爸爸的书房吧。”她带着我们走进了她爸爸的书房。房间不太大，周围摆着几个大书架。书架里放着很多书，有中文的，也有外文的，有文学、历史方面的，也有政治、哲学方面的。我看了一下儿，很多书我都不知道，我只认识鲁迅、毛泽东和邓小平的名字，因为我在国内时读过他们的书，当然是翻译成英文的。窗前是一张写字台，写字台旁边放着一台新电脑，电脑还开着呢。","Điền Phương nói: “Trước tiên tham quan phòng sách của bố mình đã.” Cô ấy dẫn chúng tôi vào phòng sách của bố. Căn phòng không lớn lắm, xung quanh kê mấy giá sách lớn. Trên giá để rất nhiều sách, có sách tiếng Trung, cũng có sách ngoại văn, có sách về văn học, lịch sử, cũng có sách về chính trị, triết học. Tôi xem qua một chút, rất nhiều sách tôi không biết, tôi chỉ biết tên Lỗ Tấn, Mao Trạch Đông và Đặng Tiểu Bình, vì hồi ở trong nước tôi đã đọc sách của họ, tất nhiên là bản dịch tiếng Anh. Trước cửa sổ là một cái bàn viết, bên cạnh bàn đặt một chiếc máy tính mới, máy tính vẫn đang bật."],["沙发后面的墙上挂着几幅字画，田芳指着这些字画给我们介绍说：“这是徐悲鸿画的画儿，那是郭沫若写的字。”田芳问我：“你知道徐悲鸿和郭沫若是谁吗？”我说不知道。我对中国了解得太少了。田芳告诉我，徐悲鸿是中国有名的画家，郭沫若是中国有名的历史学家。田芳说：“这些书和字画都是我爷爷留给我们的。”","Trên bức tường phía sau ghế sofa treo mấy bức thư họa, Điền Phương chỉ vào những bức đó giới thiệu: “Đây là tranh Từ Bi Hồng vẽ, kia là chữ Quách Mạt Nhược viết.” Điền Phương hỏi tôi: “Bạn có biết Từ Bi Hồng và Quách Mạt Nhược là ai không?” Tôi nói không biết. Tôi hiểu về Trung Quốc quá ít. Điền Phương cho tôi biết Từ Bi Hồng là họa sĩ nổi tiếng của Trung Quốc, Quách Mạt Nhược là nhà sử học nổi tiếng. Điền Phương nói: “Những sách và thư họa này đều là ông nội để lại cho chúng mình.”"],["参观完书房，田芳说：“我们到客厅坐一会儿吧，你们不是想学包饺子吗？今天，我爸爸妈妈请你们吃饺子。”我们走进客厅的时候，田芳的爸爸妈妈正准备包饺子呢。她爸爸说：“你们坐着聊天儿吧，我们两个包就行了。”田芳说：“我们一起来吧，麦克和玛丽还想学学呢。”我们洗了手就开始包饺子。","Tham quan xong phòng sách, Điền Phương nói: “Chúng ta ra phòng khách ngồi một lát nhé, chẳng phải các bạn muốn học gói sủi cảo sao? Hôm nay bố mẹ mình mời các bạn ăn sủi cảo.” Khi chúng tôi vào phòng khách, bố mẹ Điền Phương đang chuẩn bị gói sủi cảo. Bố cô ấy nói: “Các cháu cứ ngồi nói chuyện đi, hai bác gói là được rồi.” Điền Phương nói: “Mình cùng gói đi, Mike và Mary còn muốn học mà.” Chúng tôi rửa tay xong liền bắt đầu gói sủi cảo."],["来中国以后我吃过一两次饺子，但没有包过饺子，这是第一次。我不会包，包了半天才包了一个，田芳说我包的饺子像小老鼠，说得大家都笑了。我们大家一边包一边聊天儿，很热闹。我很喜欢这种欢乐的家庭气氛。","Đến Trung Quốc tôi đã ăn sủi cảo một hai lần, nhưng chưa gói bao giờ, đây là lần đầu tiên. Tôi không biết gói, gói mãi mới được một cái, Điền Phương bảo sủi cảo tôi gói giống con chuột nhắt, khiến mọi người đều bật cười. Mọi người vừa gói vừa trò chuyện, rất náo nhiệt. Tôi rất thích không khí gia đình vui vẻ như thế này."],["饺子端出来了。今天的饺子真好吃，我吃了二十多个。吃完饺子，我们又坐了一会儿，然后对两位老师说：“我们该走了，谢谢你们，我们过得很愉快。”两位老师一直送我们走出大门，对我们说：“欢迎你们常来玩儿。”","Sủi cảo được bưng ra. Sủi cảo hôm nay ngon thật, tôi ăn hơn hai mươi cái. Ăn xong, chúng tôi ngồi thêm một lúc rồi nói với hai thầy cô: “Chúng cháu phải về rồi, cảm ơn hai bác, chúng cháu đã có một ngày rất vui.” Hai thầy cô tiễn chúng tôi ra tận cổng, nói: “Lúc nào rảnh các cháu cứ đến chơi nhé.”"]]}],"grammar":[{"title":"Câu tồn hiện — ở đâu có / xuất hiện / mất đi ai, cái gì","f":["Từ chỉ nơi chốn + Động từ + 着 / 了 / bổ ngữ xu hướng + Số lượng + Danh từ"],"note":"Dùng để miêu tả ở một nơi nào đó có (tồn tại), xuất hiện hoặc mất đi người/vật. Nơi chốn đứng đầu câu, không có 在. Danh từ cuối câu thường là cái chưa xác định (一个、一辆、很多…).","ex":[["墙上挂着一张地图。","Trên tường treo một tấm bản đồ."],["门口停着很多车。","Trước cửa đậu rất nhiều xe."],["前边开过来一辆空车。","Phía trước có một chiếc xe trống chạy tới."],["我们班来了一个新同学。","Lớp mình có thêm một bạn mới."]],"warn":["Danh từ cuối câu không được là người/vật xác định: *楼上下来了王老师* là sai → 王老师从楼上下来了.","Đầu câu không thêm 在: *在墙上挂着…* là sai."]},{"title":"越来越… / 越A越B — càng ngày càng / càng… càng…","f":["越来越 + Tính từ / Động từ tâm lý","越 + A + 越 + B"],"note":"越来越: mức độ thay đổi theo thời gian. 越A越B: B thay đổi theo A.","ex":[["天气越来越冷了。","Trời càng ngày càng lạnh."],["我越来越喜欢这个城市了。","Tôi càng ngày càng thích thành phố này."],["汉语越学越有意思。","Tiếng Hán càng học càng thú vị."],["雨越下越大。","Mưa càng lúc càng to."]],"warn":["Sau 越 không thêm 很、非常、太: *越来越很冷* là sai."]}]},{"n":17,"zh":"把“福”字倒着贴在门上","vi":"Dán ngược chữ “Phúc” lên cửa","texts":[{"zh":"（一）我们把教室布置成了会场","vi":"Chúng tôi đã bố trí lớp học thành hội trường","phu":false,"pairs":[["圣诞节和新年快到了，我们班准备在圣诞节前举行一个联欢晚会，请老师们也来参加。晚会上我们要唱中文歌，用汉语讲故事，表演节目，品尝各国的特色菜。班长要求我们那天把自己亲手做的菜带到晚会上来，让大家品尝。","Giáng sinh và năm mới sắp đến, lớp chúng tôi chuẩn bị tổ chức một buổi liên hoan trước Giáng sinh, mời các thầy cô cùng đến tham dự. Trong buổi liên hoan chúng tôi sẽ hát bài hát tiếng Trung, kể chuyện bằng tiếng Hán, biểu diễn tiết mục, thưởng thức món đặc sắc của các nước. Lớp trưởng yêu cầu hôm đó mỗi người mang món mình tự tay nấu đến buổi liên hoan để mọi người cùng thưởng thức."],["玛丽说：“我们最好借一个大教室，把它布置成会场。”","Mary nói: “Tốt nhất chúng ta mượn một phòng học lớn, bố trí nó thành hội trường.”"],["前天，我们找到管理员，告诉了她借教室的事儿，她答应把那个大教室借给我们。昨天下午服务员把教室打扫了一下儿，把门和窗户也都擦得干干净净的。","Hôm kia, chúng tôi tìm gặp người quản lý, nói với cô ấy chuyện mượn phòng học, cô ấy đồng ý cho chúng tôi mượn phòng học lớn đó. Chiều hôm qua nhân viên phục vụ đã quét dọn phòng học, lau cả cửa ra vào và cửa sổ sạch bong."],["我们把桌子摆成了一个大圆圈儿，爱德华把“圣诞—新年快乐”几个大字贴在了黑板上。","Chúng tôi xếp bàn thành một vòng tròn lớn, Edward dán mấy chữ to “Giáng sinh – Năm mới vui vẻ” lên bảng đen."],["李美英说，晚会上她要和几个同学唱歌，跳舞，所以把音响也搬到教室里来了。爱德华昨天从商店买回来一棵圣诞树，我们把它摆在了教室的前边，用彩灯和彩带把它装饰得非常漂亮。","Lý Mỹ Anh nói trong buổi liên hoan cô ấy sẽ cùng mấy bạn hát và múa, vì thế đã chuyển cả loa vào phòng học. Hôm qua Edward mua từ cửa hàng về một cây thông Noel, chúng tôi đặt nó ở phía trước lớp, dùng đèn màu và dây kim tuyến trang trí rất đẹp."],["安娜是我们班最小的同学，她的生日正好是十二月二十五号，所以同学们还为她准备了一份生日礼物和一个生日蛋糕，但是我们还没把这事儿告诉她。我们想，到晚会上再把生日礼物送给她，给她一个惊喜，让她在中国过一个快乐的生日。","Anna là bạn nhỏ tuổi nhất lớp, sinh nhật bạn ấy vừa đúng ngày 25 tháng 12, nên các bạn còn chuẩn bị cho bạn ấy một món quà sinh nhật và một chiếc bánh sinh nhật, nhưng chúng tôi chưa nói chuyện này với bạn ấy. Chúng tôi định đến buổi liên hoan mới tặng quà, tạo cho bạn ấy một bất ngờ, để bạn ấy có một sinh nhật vui vẻ ở Trung Quốc."],["我们把教室布置好以后，请老师来看了看，老师高兴地说：“你们把教室布置得真漂亮！”","Sau khi bố trí xong phòng học, chúng tôi mời thầy cô đến xem, thầy cô vui vẻ nói: “Các em trang trí phòng học đẹp thật!”"],["为了开好这个联欢会，同学们都认真地做了准备。明天晚上六点钟，我们的晚会就要开始了，欢迎大家来参加。","Để tổ chức tốt buổi liên hoan này, các bạn đều chuẩn bị rất chu đáo. Sáu giờ tối mai, buổi liên hoan của chúng tôi sẽ bắt đầu, hoan nghênh mọi người đến tham dự."]]},{"zh":"（二）把对联儿贴在大门两边","vi":"Dán câu đối ở hai bên cổng","phu":false,"pairs":[["高老师：哎，这幅画儿挂在什么地方比较好？","Cô Cao: Này, bức tranh này treo ở chỗ nào thì đẹp hơn?"],["王老师：我想把它挂在中间。对了，小林还没把水仙花送来吧？","Thầy Vương: Anh định treo nó ở giữa. À phải rồi, Tiểu Lâm vẫn chưa mang hoa thủy tiên đến à?"],["高老师：已经送来了，我把它摆在卧室里了。你来看，开得可好了。","Cô Cao: Mang đến rồi, em để nó trong phòng ngủ. Anh đến xem này, nở đẹp lắm."],["王老师：把它摆在客厅里比较好。我把“福”字贴在门上吧。","Thầy Vương: Đặt nó ở phòng khách thì hơn. Để anh dán chữ “Phúc” lên cửa nhé."],["高老师：把你写的对联儿也贴上去吧。（读对联儿）“新年新春吉祥，百行百业……”你是不是把“兴”字写成“旺”字了？","Cô Cao: Dán cả câu đối anh viết lên luôn đi. (Đọc câu đối) “Năm mới xuân mới cát tường, trăm ngành trăm nghề…” Có phải anh viết chữ “hưng” thành chữ “vượng” rồi không?"],["王老师：哦，可不是嘛，写错了。应该是“新年新春吉祥，百行百业兴旺”。","Thầy Vương: Ồ, đúng thế thật, viết sai rồi. Phải là “Năm mới xuân mới cát tường, trăm ngành trăm nghề hưng vượng”."]]},{"zh":"（三）把“福”字倒着贴在门上","vi":"Dán ngược chữ “Phúc” lên cửa","phu":false,"pairs":[["麦克：田芳，这就是你说的对联儿吗？","Mike: Điền Phương, đây chính là câu đối cậu nói à?"],["田芳：是啊。","Điền Phương: Đúng vậy."],["麦克：门上这个字怎么念？","Mike: Chữ trên cửa này đọc thế nào?"],["田芳：你仔细看看，认识不认识？","Điền Phương: Cậu nhìn kỹ xem, có biết không?"],["麦克：没学过。","Mike: Mình chưa học."],["田芳：这不是幸福的“福”字吗？过春节的时候，差不多家家都贴“福”字。","Điền Phương: Đây chẳng phải chữ “phúc” trong “hạnh phúc” sao? Khi đón Tết, hầu như nhà nào cũng dán chữ “Phúc”."],["麦克：这是幸福的“福”字？为什么把“福”字倒着贴在门上呢？","Mike: Đây là chữ “phúc” trong “hạnh phúc” à? Sao lại dán ngược chữ “Phúc” lên cửa?"],["田芳：这样，人们一看见就会说“福倒了”，听声音就是“福到了”。","Điền Phương: Như vậy, người ta vừa nhìn thấy sẽ nói “phúc đảo rồi”, nghe âm thì thành “phúc đến rồi”."],["麦克：哦，那我也去买一些“福”字来，把它倒着贴在门上、床上、桌子上、椅子上、沙发上、冰箱上、洗衣机上、空调上……等着幸福来找我。","Mike: À, vậy mình cũng đi mua ít chữ “Phúc” về, dán ngược lên cửa, lên giường, lên bàn, lên ghế, lên sofa, lên tủ lạnh, lên máy giặt, lên điều hòa… chờ hạnh phúc đến tìm mình."]]},{"zh":"（读后复述）现在该你吹气了","vi":"Giờ đến lượt bố thổi rồi","phu":true,"pairs":[["爸爸带着三岁的儿子坐火车去看奶奶。在火车上，儿子喜欢把头伸到窗外去。爸爸对他说：“儿子，小心点儿，别把头伸到窗外去。”可是男孩儿不听爸爸的话，还是把头伸到窗外。","Bố dẫn cậu con trai ba tuổi đi tàu hỏa về thăm bà nội. Trên tàu, cậu con trai thích thò đầu ra ngoài cửa sổ. Bố nói với cậu: “Con ơi, cẩn thận một chút, đừng thò đầu ra ngoài cửa sổ.” Nhưng cậu bé không nghe lời bố, vẫn thò đầu ra ngoài."],["这时爸爸悄悄地把儿子的帽子摘了下来，放在自己身后，然后对他说：“你看，风把你的帽子刮跑了。”儿子急得哭了，哭着要他的帽子。爸爸说：“好，你对着窗口吹一口气，帽子就回来了。”","Lúc đó bố lặng lẽ cởi chiếc mũ của con xuống, giấu sau lưng mình, rồi nói với cậu: “Con xem, gió thổi bay mũ của con rồi.” Cậu con trai cuống quá khóc òa, vừa khóc vừa đòi mũ. Bố nói: “Được rồi, con thổi một hơi ra cửa sổ thì mũ sẽ quay lại.”"],["儿子就对着窗口吹了一口气，爸爸很快把帽子戴到他的头上。儿子笑了。他想，这太有意思了。就一下子把爸爸的帽子摘了下来，扔到车窗外边去了，然后高兴地对爸爸说：“爸爸，快！现在该你吹气了。”","Cậu con trai liền thổi một hơi ra cửa sổ, bố nhanh tay đội mũ lên đầu cậu. Cậu bé cười. Cậu nghĩ, cái này thú vị quá. Thế là cậu giật phắt mũ của bố xuống, ném ra ngoài cửa sổ tàu, rồi vui vẻ nói với bố: “Bố ơi, nhanh lên! Giờ đến lượt bố thổi rồi.”"]]}],"grammar":[{"title":"Câu chữ 把 (1) — xử lý đồ vật: đặt ở đâu, đưa cho ai, biến thành gì","f":["Chủ ngữ + 把 + Đồ vật + Động từ + 在 / 到 + Nơi chốn","Chủ ngữ + 把 + Đồ vật + Động từ + 给 + Người","Chủ ngữ + 把 + Đồ vật + Động từ + 成 + Kết quả mới"],"note":"Câu 把 nhấn mạnh việc chủ ngữ tác động lên đồ vật làm nó thay đổi vị trí, chủ sở hữu hoặc trạng thái. Với 3 kiểu V在/到, V给, V成 có tân ngữ phía sau thì gần như bắt buộc dùng 把.","ex":[["我把花儿摆在客厅里了。","Tôi bày hoa ở phòng khách rồi."],["他把“福”字倒着贴在门上。","Anh ấy dán ngược chữ Phúc lên cửa."],["请把这本书还给他。","Hãy trả quyển sách này cho anh ấy."],["她把这篇课文翻译成英文了。","Cô ấy dịch bài này sang tiếng Anh rồi."]],"warn":[]},{"title":"Lặp danh từ đơn âm — mỗi…, …nào cũng","f":["Danh từ / lượng từ đơn âm lặp lại: 家家、人人、天天、年年"],"note":"Lặp lại để chỉ “mỗi, tất cả”, phía sau thường có 都.","ex":[["春节的时候，家家都贴“福”字。","Tết thì nhà nào cũng dán chữ Phúc."],["他天天都去锻炼。","Ngày nào anh ấy cũng đi tập."]],"warn":[]},{"title":"Cách nói trong bài: 可不是嘛","f":["可不是(嘛) — đúng vậy, chứ còn gì nữa (đồng ý với người nói)"],"note":"Dùng khi hoàn toàn đồng ý với ý kiến người kia, giọng khẳng định mạnh.","ex":[["— 今天真冷啊！— 可不是嘛！","— Hôm nay lạnh thật! — Chứ còn gì nữa!"]],"warn":[]}]},{"n":18,"zh":"请把护照和机票给我","vi":"Xin đưa hộ chiếu và vé máy bay cho tôi","texts":[{"zh":"（一）请把护照和机票给我","vi":"Xin đưa hộ chiếu và vé máy bay cho tôi","phu":false,"pairs":[["关建平：（对夏雨）我们先去办理登机手续，把行李托运了。","Quan Kiến Bình: (Nói với Hạ Vũ) Chúng ta đi làm thủ tục lên máy bay trước, gửi hành lý đã."],["服务员：请把护照和机票给我。哪个箱子要托运？把它放上去吧。这是登机牌儿，请拿好。","Phục vụ: Xin đưa hộ chiếu và vé máy bay cho tôi. Vali nào cần ký gửi? Anh đặt nó lên đây. Đây là thẻ lên máy bay, xin cầm cẩn thận."],["关建平：谢谢！","Quan Kiến Bình: Cảm ơn!"],["服务员：这位女士，你口袋里装的是什么？","Phục vụ: Thưa chị, trong túi chị đựng gì vậy?"],["夏雨：没有什么呀！","Hạ Vũ: Có gì đâu!"],["服务员：请把口袋里的东西都掏出来。","Phục vụ: Xin lấy hết đồ trong túi ra."],["夏雨：啊，是几把钥匙和两个硬币。","Hạ Vũ: À, là mấy chiếc chìa khóa và hai đồng xu."],["服务员：好了。请进去吧。","Phục vụ: Được rồi. Mời chị vào."],["关建平：把手提包放到行李箱里去吧。","Quan Kiến Bình: Để túi xách lên khoang hành lý đi."],["夏雨：等一下儿，先把相机拿出来，我想在飞机上照两张照片。","Hạ Vũ: Đợi chút, lấy máy ảnh ra trước đã, em muốn chụp mấy tấm ảnh trên máy bay."],["关建平：给你。对了，相机里还没有电池呢，我先把电池装上。","Quan Kiến Bình: Đây. À phải rồi, trong máy ảnh còn chưa có pin, để anh lắp pin vào trước."]]},{"zh":"（二）你把灯打开","vi":"Anh bật đèn lên đi","phu":false,"pairs":[["夏雨：这里边有点儿暗。","Hạ Vũ: Trong này hơi tối."],["关建平：你把灯打开。","Quan Kiến Bình: Em bật đèn lên đi."],["夏雨：开关在哪儿呢？","Hạ Vũ: Công tắc ở đâu nhỉ?"],["关建平：在座位的扶手上。","Quan Kiến Bình: Ở trên tay vịn của ghế."],["空姐：飞机马上就要起飞了，请大家把安全带系好，把手机关上……","Tiếp viên: Máy bay sắp cất cánh, xin quý khách thắt dây an toàn và tắt điện thoại…"],["夏雨：我还不会系安全带呢。","Hạ Vũ: Em vẫn chưa biết thắt dây an toàn."],["关建平：把这个插头往里一插就行了。","Quan Kiến Bình: Cắm cái chốt này vào trong là được."],["夏雨：怎么打开呢？","Hạ Vũ: Mở ra thế nào?"],["关建平：把卡子扳一下儿就打开了。","Quan Kiến Bình: Gạt cái khóa một cái là mở ra."],["夏雨：啊，打开了。你看，咖啡都凉了，快把它喝了吧。","Hạ Vũ: À, mở được rồi. Anh xem, cà phê nguội cả rồi, mau uống đi."],["夏雨：哎呀！","Hạ Vũ: Ôi trời!"],["关建平：怎么了？","Quan Kiến Bình: Sao thế?"],["夏雨：你把杯子碰倒了，咖啡全洒了。","Hạ Vũ: Anh làm đổ cốc rồi, cà phê đổ hết ra."],["关建平：快拿纸把桌子擦擦。","Quan Kiến Bình: Mau lấy giấy lau bàn đi."]]},{"zh":"（综合填空）找钱","vi":"Trả lại tiền thừa","phu":true,"pairs":[["下班以后，天都快黑了，我想顺便买点儿菜带回家，就向一个菜摊儿走去。卖菜的是一个小伙子。问了价钱以后，我拿起一把菜，对他说：“把这些菜给我称一下儿。”“您给3块吧！”他称了以后说。“给，找吧。”我给了他一张10块的钱。“您没零钱吗？”他问。“没有了，就这一张。”","Tan làm, trời đã sắp tối, tôi định tiện thể mua ít rau mang về nhà nên đi về phía một sạp rau. Người bán rau là một chàng trai trẻ. Hỏi giá xong, tôi cầm một bó rau lên, nói với cậu ấy: “Cân giúp tôi chỗ rau này.” “Chị đưa 3 tệ nhé!” cậu ấy cân xong nói. “Đây, trả lại cho tôi nhé.” Tôi đưa cậu ấy một tờ 10 tệ. “Chị không có tiền lẻ à?” cậu ấy hỏi. “Hết rồi, chỉ còn tờ này thôi.”"],["他找了半天，才把一把零钱放在我手里说：“您数一数吧。”我接过钱没有数，往口袋里一塞，拿起菜，骑上车就走了。","Cậu ấy tìm mãi mới đặt một nắm tiền lẻ vào tay tôi, nói: “Chị đếm lại xem.” Tôi cầm tiền không đếm, nhét vào túi, cầm rau lên xe đạp đi luôn."],["骑了一会儿，我忽然觉得不对，就想，他找了我多少钱啊，我从车上下来了。从口袋里把钱拿出来认真地数了数，小伙子找我了97块，多找给我90块钱！还回去不回去呢？已经走这么远了……","Đạp xe được một lúc, tôi chợt thấy có gì đó không đúng, nghĩ: cậu ấy trả lại mình bao nhiêu tiền nhỉ, thế là tôi xuống xe. Lấy tiền trong túi ra đếm kỹ, cậu ấy trả lại tôi 97 tệ, trả thừa cho tôi 90 tệ! Có quay lại trả không đây? Đã đi xa thế này rồi…"],["就在我这么想的时候，脸上马上觉得发热。我怎么会有这种不好的想法，我的心变坏了吗？想到这儿，就立刻骑上车回去找那个卖菜的小伙子。","Đúng lúc tôi nghĩ vậy, mặt tôi bỗng thấy nóng bừng. Sao mình lại có ý nghĩ không hay như thế, lòng mình trở nên xấu rồi sao? Nghĩ đến đây, tôi lập tức lên xe quay lại tìm cậu bán rau."],["天已经黑了。我远远看见那个小伙子正准备走，就跑过去把他叫住：“喂，等一下儿！”“怎么了？”小伙子问我。“你把钱找错了。”“少找了吗？”“不，你多找了。”“不会吧？”“怎么不会呢？你把我给你的10块钱看成100块的了。”我说，“给，这是你多找的90块钱。”我把多找的钱还给了他。","Trời đã tối. Tôi nhìn từ xa thấy cậu ấy đang chuẩn bị về, liền chạy tới gọi cậu lại: “Này, đợi một chút!” “Sao thế ạ?” cậu ấy hỏi tôi. “Cậu trả nhầm tiền rồi.” “Trả thiếu ạ?” “Không, cậu trả thừa.” “Không thể nào?” “Sao lại không thể? Cậu nhìn tờ 10 tệ tôi đưa thành tờ 100 tệ rồi.” Tôi nói: “Đây, đây là 90 tệ cậu trả thừa.” Tôi trả lại số tiền thừa cho cậu ấy."],["他有点儿不太相信地把钱接过去，很快，就感激地对我说：“谢谢了！大哥，谢谢你了！你真是好人。”我没有说话，骑上车就走了。这时，我心里才觉得轻松了。","Cậu ấy hơi không tin nổi, cầm lấy tiền, rồi rất nhanh cảm kích nói với tôi: “Cảm ơn ạ! Anh ơi, cảm ơn anh! Anh đúng là người tốt.” Tôi không nói gì, lên xe đi luôn. Lúc này, trong lòng tôi mới thấy nhẹ nhõm."],["（注：这个故事发生在上个世纪80年代，当时的10元人民币与100元的色调差不多。）","(Chú thích: câu chuyện xảy ra vào những năm 80 của thế kỷ trước, khi đó tờ 10 tệ và tờ 100 tệ có màu sắc gần giống nhau.)"]]}],"grammar":[{"title":"Câu chữ 把 (2) — điều kiện bắt buộc","f":["Chủ ngữ + 把 + Tân ngữ (xác định) + Động từ + thành phần khác","Thành phần khác: 了 / động từ lặp / bổ ngữ / tân ngữ thứ hai","Phủ định, động từ năng nguyện: 不 / 没 / 能 / 要 / 想 + 把 + …"],"note":"Động từ trong câu 把 không được đứng một mình. Tân ngữ của 把 phải là cái người nghe đã biết (这本书, 护照…). Từ phủ định và động từ năng nguyện luôn đặt trước 把.","ex":[["请把护照和机票给我。","Xin đưa hộ chiếu và vé máy bay cho tôi."],["快把桌子擦擦。","Mau lau cái bàn đi."],["请把安全带系好。","Xin thắt dây an toàn."],["他没把书还给我。","Anh ấy chưa trả sách cho tôi."],["我想把这件事告诉妈妈。","Tôi muốn kể chuyện này cho mẹ."],["现在不要把书打开。","Bây giờ đừng mở sách ra."]],"warn":["Không dùng 把 với: 有、是、在、来、去、喜欢、知道、觉得、看见、毕业.","Sai: *他把书没还给我* → Đúng: 他没把书还给我."]}]},{"n":19,"zh":"我的腿被自行车撞伤了","vi":"Chân tôi bị xe đạp đâm bị thương","texts":[{"zh":"（一）我的腿被自行车撞伤了","vi":"Chân tôi bị xe đạp đâm bị thương","phu":false,"pairs":[["罗兰：你的腿怎么了？","Roland: Chân cậu sao thế?"],["玛丽：星期天我骑车上街的时候，被一个小伙子撞倒了，从车上摔下来把腿摔伤了。","Mary: Chủ nhật lúc mình đạp xe ra phố, bị một thanh niên đâm ngã, ngã từ trên xe xuống bị thương ở chân."],["罗兰：要紧吗？","Roland: Có nặng không?"],["玛丽：流了一点儿血，不要紧。","Mary: Chảy một chút máu, không sao."],["罗兰：还疼吗？","Roland: Còn đau không?"],["玛丽：还有点儿疼。","Mary: Vẫn còn hơi đau."],["罗兰：伤着骨头了没有？","Roland: Có bị thương đến xương không?"],["玛丽：我被撞倒后，小伙子看我躺在地上，马上叫了辆出租车，把我送到了医院。大夫给我检查了一下儿，还好，没伤着骨头。","Mary: Sau khi mình bị đâm ngã, cậu thanh niên thấy mình nằm dưới đất liền gọi ngay một chiếc taxi, đưa mình đến bệnh viện. Bác sĩ kiểm tra cho mình một chút, may mà không bị thương đến xương."],["罗兰：那个小伙子是哪儿的？","Roland: Cậu thanh niên đó ở đâu?"],["玛丽：是北京大学的学生。昨天他还来看过我。他也觉得挺不好意思的。我说，没什么，你又不是故意的。","Mary: Là sinh viên Đại học Bắc Kinh. Hôm qua cậu ấy còn đến thăm mình. Cậu ấy cũng thấy rất ngại. Mình nói không sao, cậu đâu có cố ý."],["罗兰：街上人多车也多，骑车上街的时候，一定要特别小心。","Roland: Trên đường người đông xe nhiều, lúc đạp xe ra phố nhất định phải hết sức cẩn thận."],["玛丽：可不是！","Mary: Đúng thế!"]]},{"zh":"（二）钱包儿让小偷儿偷走了","vi":"Ví bị kẻ trộm lấy mất","phu":false,"pairs":[["大山：真倒霉！","Đại Sơn: Xui thật!"],["爱德华：怎么了？","Edward: Sao thế?"],["大山：唉，别提了，我的钱包儿让小偷儿偷走了。","Đại Sơn: Ôi, đừng nhắc nữa, ví của mình bị kẻ trộm lấy mất rồi."],["爱德华：丢了多少钱？","Edward: Mất bao nhiêu tiền?"],["大山：钱不多，才几十块钱。但我最近遇到好几件倒霉事儿了。","Đại Sơn: Tiền không nhiều, chỉ mấy chục tệ. Nhưng dạo này mình gặp mấy chuyện xui rồi."],["爱德华：都遇到什么倒霉事儿了？","Edward: Gặp những chuyện xui gì?"],["大山：我刚买了一辆自行车，就叫人骑走了，到现在也没送回来。","Đại Sơn: Mình vừa mua một chiếc xe đạp thì bị người ta đạp mất, đến giờ vẫn chưa mang trả lại."],["爱德华：你还等着给你送回来呀？","Edward: Cậu còn đợi người ta mang trả lại cho cậu à?"],["大山：上星期跟朋友一起去长城，出发时天气好好儿的，没想到，刚到就下雨了。雨下得还特别大，我们又没带雨伞，个个都被淋得像落汤鸡似的，衣服全都湿了。前天我坐出租车要去“首都剧场”，差点儿被司机拉到“首都机场”。他说我的音发得不准，把“剧场”说成“机场”了。你说可气不可气？","Đại Sơn: Tuần trước mình cùng bạn đi Trường Thành, lúc xuất phát trời còn đẹp, không ngờ vừa đến nơi thì mưa. Mưa lại rất to, bọn mình lại không mang ô, ai cũng bị ướt như chuột lột, quần áo ướt hết. Hôm kia mình đi taxi định đến “Nhà hát Thủ đô”, suýt nữa bị tài xế chở đến “Sân bay Thủ đô”. Anh ta nói mình phát âm không chuẩn, nói “nhà hát” thành “sân bay”. Cậu nói có bực không?"],["爱德华：怎么倒霉的事儿都让你碰上了？","Edward: Sao chuyện xui nào cũng để cậu gặp phải thế?"],["大山：所以，前几天我遇到一个算命的，就叫他给我算了一下儿。","Đại Sơn: Vì vậy, mấy hôm trước mình gặp một ông thầy bói, liền nhờ ông ấy xem cho một quẻ."],["爱德华：结果怎么样？","Edward: Kết quả thế nào?"],["大山：他说我今年运气不太好，明年就好了。为了感谢他，我给了他一百块钱。朋友们都说我傻，花钱受骗。没想到，那天跟大家一起去爬山，因为在山上抽烟，又被公园管理员罚了五十块钱。你说倒霉不倒霉？","Đại Sơn: Ông ấy nói năm nay mình vận không tốt lắm, sang năm sẽ tốt. Để cảm ơn ông ấy, mình đưa ông ấy một trăm tệ. Bạn bè đều bảo mình ngốc, mất tiền còn bị lừa. Không ngờ hôm đó cùng mọi người đi leo núi, vì hút thuốc trên núi lại bị người quản lý công viên phạt năm mươi tệ. Cậu nói có xui không?"],["爱德华：要是山上的树被你点着了，就更倒霉了。","Edward: Nếu cây trên núi bị cậu làm cháy thì còn xui hơn nữa."],["大山：你说得也对。所以从下星期起，我决定把烟戒掉，不抽了。","Đại Sơn: Cậu nói cũng đúng. Vì vậy từ tuần sau, mình quyết định cai thuốc, không hút nữa."],["爱德华：为什么从下星期开始呢？","Edward: Sao lại bắt đầu từ tuần sau?"],["大山：我的烟还能抽到下星期，要是不抽完就浪费了。","Đại Sơn: Thuốc của mình vẫn còn hút được đến tuần sau, nếu không hút hết thì lãng phí."]]},{"zh":"（综合填空）我被解雇了","vi":"Tôi bị đuổi việc rồi","phu":true,"pairs":[["“你还在那家花店工作吗？”“不了，我被老板炒鱿鱼了。”“为什么？”","“Cậu vẫn làm ở cửa hàng hoa đó à?” “Không nữa, mình bị ông chủ cho nghỉ việc rồi.” “Sao vậy?”"],["“每次给人家送花儿之前，我得在每束花儿里放上一张卡片。上次，我把两张卡片放错了。”“你是怎么放错的？”","“Mỗi lần trước khi giao hoa cho khách, mình phải đặt một tấm thiệp vào mỗi bó hoa. Lần trước, mình đặt nhầm hai tấm thiệp.” “Cậu đặt nhầm thế nào?”"],["“我把送到婚礼上去的花儿里放上了一张‘致以深深的哀悼’；而那张新婚贺卡却被我放到了送给葬礼的花儿里去了。”“上面写的什么？”“祝你们在新的家幸福快乐！”","“Mình đặt vào bó hoa gửi đến đám cưới một tấm thiệp ‘Xin gửi lời chia buồn sâu sắc’; còn tấm thiệp mừng tân hôn thì lại bị mình đặt vào bó hoa gửi đến đám tang.” “Trên đó viết gì?” “Chúc các bạn hạnh phúc vui vẻ ở ngôi nhà mới!”"]]}],"grammar":[{"title":"Câu bị động 被 / 叫 / 让","f":["Chủ ngữ (bị tác động) + 被 / 叫 / 让 + Người làm + Động từ + thành phần khác","Chủ ngữ + 被 + Động từ + thành phần khác (bỏ người làm)","Phủ định: 没 + 被 + … (không có 了 ở cuối)"],"note":"Dùng khi muốn nói người/vật “bị” hoặc “được” tác động. 被 có thể bỏ người làm; 叫 và 让 thì phải có người làm, hay dùng trong khẩu ngữ. Động từ phía sau cũng phải có thêm 了, bổ ngữ…","ex":[["我的腿被自行车撞伤了。","Chân tôi bị xe đạp đâm bị thương."],["我的钱包被偷走了。","Ví tôi bị trộm mất rồi."],["我的自行车叫人骑走了。","Xe đạp tôi bị người ta lấy đi mất rồi."],["蛋糕让孩子吃完了。","Bánh kem bị con ăn hết rồi."],["骨头没被撞伤。","Xương không bị va trúng."]],"warn":["Phủ định, động từ năng nguyện đặt trước 被: *骨头被车没有撞伤* → 骨头没有被车撞伤.","Sai: *自行车叫骑走了* (thiếu người làm) → 自行车被骑走了 / 自行车叫人骑走了."]},{"title":"又 nhấn mạnh phủ định · 可 + Động từ","f":["又 + 不 / 没 + … — đâu có…, có phải… đâu","可 + Động từ → tính từ: 可气、可爱、可怕、可笑、可惜"],"note":"又 đứng trước từ phủ định để nhấn mạnh, thường dùng để giải thích hoặc an ủi. 可 + V tạo thành tính từ mang nghĩa “đáng…”.","ex":[["你又不是故意的，没关系。","Anh đâu có cố ý, không sao đâu."],["我又没去过，怎么知道？","Tôi có đi đâu, sao mà biết?"],["你说可气不可气？","Anh nói xem có tức không?"]],"warn":[]},{"title":"Cách nói trong bài: 还好 · 才 + số lượng","f":["还好 — may mà, cũng may (tình huống không tệ như lo)","才 + số lượng — chỉ có, mới có (cho là ít)"],"note":"还好 dùng khi chuyện xấu xảy ra nhưng kết quả vẫn ổn. 才 đứng trước số lượng nhấn mạnh là ít.","ex":[["还好，没伤着骨头。","Cũng may là không bị thương vào xương."],["钱不多，才几十块钱。","Tiền không nhiều, chỉ có mấy chục tệ."]],"warn":[]}]},{"n":20,"zh":"我看得懂，但是听不懂","vi":"Tôi xem hiểu được, nhưng nghe không hiểu","texts":[{"zh":"（一）我看得懂，但是听不懂","vi":"Tôi xem hiểu được, nhưng nghe không hiểu","phu":false,"pairs":[["玛丽：你看过京剧吗？","Mary: Cậu xem Kinh kịch bao giờ chưa?"],["山本：看过一次。","Yamamoto: Xem một lần rồi."],["玛丽：看得懂吗？","Mary: Xem có hiểu không?"],["山本：看得懂，但是听不懂。看了演出能猜出大概的意思。","Yamamoto: Xem thì hiểu, nhưng nghe không hiểu. Xem biểu diễn có thể đoán ra đại khái ý nghĩa."],["玛丽：我也是，一点儿也听不懂演员唱的是什么，只是觉得很热闹。","Mary: Mình cũng vậy, diễn viên hát gì mình chẳng nghe hiểu chút nào, chỉ thấy rất náo nhiệt."],["山本：我觉得京剧唱得特别好听，武打动作也很精彩。我还喜欢京剧的脸谱，京剧用各种脸谱来表现人物的社会地位和性格，十分有趣。","Yamamoto: Mình thấy Kinh kịch hát cực kỳ hay, động tác võ thuật cũng rất đặc sắc. Mình còn thích mặt nạ hóa trang của Kinh kịch, Kinh kịch dùng các kiểu vẽ mặt để thể hiện địa vị xã hội và tính cách nhân vật, vô cùng thú vị."],["玛丽：京剧的服装也很美，我想买一套带回国去。","Mary: Trang phục Kinh kịch cũng rất đẹp, mình muốn mua một bộ mang về nước."],["山本：你怎么这么喜欢京剧呢？","Yamamoto: Sao cậu thích Kinh kịch thế?"],["玛丽：我是受中文老师的影响，他可是一个京剧迷。我想，京剧是中国的传统艺术，要把汉语学好，也应该多了解一些中国文化。","Mary: Mình bị ảnh hưởng từ thầy dạy tiếng Trung, thầy ấy là một người mê Kinh kịch đấy. Mình nghĩ Kinh kịch là nghệ thuật truyền thống của Trung Quốc, muốn học giỏi tiếng Hán thì cũng nên tìm hiểu thêm về văn hóa Trung Quốc."],["山本：要是有时间的话，咱们一起去看一次，好吗？","Yamamoto: Nếu có thời gian, chúng ta cùng đi xem một lần nhé?"],["玛丽：好啊。","Mary: Được đấy."]]},{"zh":"（二）她有事，去不了","vi":"Cô ấy có việc, không đi được","phu":false,"pairs":[["昨天我给山本打电话，约她晚上一起去看京剧。但是她说晚上有事，去不了。所以我们就决定今天晚上去。","Hôm qua tôi gọi điện cho Yamamoto, hẹn cô ấy tối cùng đi xem Kinh kịch. Nhưng cô ấy nói tối có việc, không đi được. Vì vậy chúng tôi quyết định tối nay đi."],["我们是下午五点半出发的。正是下班时间，路上人多车也多。公共汽车上不去，我们只好打的。我担心买不到票，但是山本说，票好买，肯定买得到。","Chúng tôi xuất phát lúc năm rưỡi chiều. Đúng giờ tan tầm, trên đường người đông xe cũng đông. Xe buýt không lên được, chúng tôi đành bắt taxi. Tôi lo không mua được vé, nhưng Yamamoto nói vé dễ mua, chắc chắn mua được."],["到了剧场，山本说要买前十排的，因为她的眼睛不太好，坐得太远看不清楚。但是，前十排的票都卖完了，没买到，我们买的是十二排的。","Đến nhà hát, Yamamoto nói muốn mua vé mười hàng đầu, vì mắt cô ấy không tốt lắm, ngồi xa quá nhìn không rõ. Nhưng vé mười hàng đầu đã bán hết, không mua được, chúng tôi mua vé hàng mười hai."],["这个剧场不大，估计坐不下一千人。离开演还有十多分钟，人差不多都坐满了。","Nhà hát này không lớn, ước chừng không chứa nổi một nghìn người. Còn hơn mười phút nữa mới mở màn mà người đã ngồi gần kín."],["我拿了一张节目单。上面全是中文，没有英文，我看不懂。山本看了看说：“这是一个古代神话故事。说的是天上一个仙女，很羡慕人间的生活，就偷偷儿来到人间，跟一个小伙子结了婚。后边的内容我也看不懂。不过，不用担心，看不懂节目单，一定看得懂表演。”","Tôi cầm một tờ chương trình. Trên đó toàn tiếng Trung, không có tiếng Anh, tôi đọc không hiểu. Yamamoto xem qua rồi nói: “Đây là một câu chuyện thần thoại cổ đại. Kể về một nàng tiên trên trời rất ngưỡng mộ cuộc sống trần gian, liền lén xuống trần, kết hôn với một chàng trai. Nội dung phía sau mình cũng đọc không hiểu. Nhưng đừng lo, đọc không hiểu tờ chương trình thì chắc chắn xem hiểu được màn biểu diễn.”"],["看完以后，我大概看懂了这个故事。我对山本说，以后周末，我们还来看吧，京剧真有意思。","Xem xong, tôi đại khái hiểu được câu chuyện này. Tôi nói với Yamamoto, sau này cuối tuần chúng mình lại đến xem nhé, Kinh kịch thú vị thật."]]},{"zh":"（综合填空）南辕北辙","vi":"Nam viên bắc triệt (Muốn đi Nam lại đánh xe lên Bắc)","phu":true,"pairs":[["这是中国古代的一个故事。前边跑过来了一辆马车，车上坐着一个大富翁，后面放着一个大箱子，前面还坐着一个赶车的。赶车的不停地赶着马，马车跑得飞快。","Đây là một câu chuyện thời cổ đại Trung Quốc. Phía trước có một cỗ xe ngựa chạy tới, trên xe ngồi một ông phú hộ lớn, phía sau đặt một chiếc rương lớn, phía trước còn có một người đánh xe. Người đánh xe không ngừng giục ngựa, xe ngựa chạy nhanh như bay."],["路上走过来一位老人。老人挑着水。大富翁看见这位老人，就叫赶车的停下车，想向老人要点儿水喝。老人问他们要到什么地方去，富翁大声地说：“我们要到楚国去。”","Trên đường có một ông lão đi tới. Ông lão đang gánh nước. Ông phú hộ nhìn thấy ông lão liền bảo người đánh xe dừng xe, muốn xin ông lão chút nước uống. Ông lão hỏi họ định đi đâu, ông phú hộ nói to: “Chúng tôi đi nước Sở.”"],["老人一听就笑了，他对富翁说：“你们走错了，楚国在南边，应该往南走，怎么往北走呢？”富翁说：“没关系，你看，我的马跑得很快。”老人又说：“你的马跑得再快，可是这不是去楚国的路啊。马跑得越快离楚国越远。”","Ông lão vừa nghe đã bật cười, nói với ông phú hộ: “Các ông đi nhầm rồi, nước Sở ở phía nam, phải đi về phía nam, sao lại đi về phía bắc?” Ông phú hộ nói: “Không sao, ông xem, ngựa của tôi chạy rất nhanh.” Ông lão lại nói: “Ngựa của ông có chạy nhanh đến đâu thì đây cũng không phải đường đến nước Sở. Ngựa chạy càng nhanh thì càng xa nước Sở.”"],["“没问题。”大富翁指着车上的箱子说，“您看，这个大箱子里装着很多钱呢。”“你有很多钱，可是走的方向不对，是到不了楚国的。”大富翁又指着赶车的说：“你看我这个车夫，身强力壮，赶车的技术也特别好。”","“Không vấn đề gì.” Ông phú hộ chỉ vào chiếc rương trên xe nói: “Ông xem, trong rương lớn này đựng rất nhiều tiền đấy.” “Ông có nhiều tiền, nhưng đi sai hướng thì không đến được nước Sở đâu.” Ông phú hộ lại chỉ vào người đánh xe nói: “Ông xem người đánh xe này của tôi, khỏe mạnh vạm vỡ, kỹ thuật đánh xe cũng cực giỏi.”"],["老人觉得这位先生简直不懂道理，就说：“你的车夫是不错。可是，楚国在南边，你却要他赶着车往北跑，怎么能到得了楚国呢？”大富翁听了老人的话，不高兴地说：“我们已经走了好几百里路了，怎么能再往回走呢？”说完他就让赶车的继续赶着车一直往北跑去，车越跑越快，一会儿就看不见了。","Ông lão thấy ông này thật chẳng hiểu lý lẽ gì, bèn nói: “Người đánh xe của ông giỏi thật. Nhưng nước Sở ở phía nam, ông lại bắt anh ta đánh xe chạy về phía bắc, làm sao đến được nước Sở?” Ông phú hộ nghe xong không vui, nói: “Chúng tôi đã đi mấy trăm dặm rồi, sao có thể quay lại được?” Nói xong ông ta bảo người đánh xe tiếp tục đánh xe chạy thẳng về phía bắc, xe càng chạy càng nhanh, chẳng mấy chốc đã không thấy đâu nữa."]]}],"grammar":[{"title":"Bổ ngữ khả năng (1) — có thể / không thể làm được","f":["Khẳng định: Động từ + 得 + Bổ ngữ kết quả / xu hướng","Phủ định: Động từ + 不 + Bổ ngữ kết quả / xu hướng","Câu hỏi: V得… V不…？ / V得…吗？"],"note":"Chèn 得 hoặc 不 vào giữa động từ và bổ ngữ để nói khả năng làm được hay không, do điều kiện khách quan hoặc năng lực.","ex":[["我看得懂，但是听不懂。","Tôi xem thì hiểu, nhưng nghe thì không hiểu."],["黑板上的字你看得清楚看不清楚？","Chữ trên bảng bạn có nhìn rõ không?"],["今天的作业太多，我做不完。","Bài tập hôm nay nhiều quá, tôi làm không xong."],["门太小，车开不进去。","Cửa nhỏ quá, xe không lái vào được."]],"warn":["Câu 把 không dùng bổ ngữ khả năng: *我把作业做不完* là sai."]},{"title":"V得了 / V不了 (liǎo) · V得下 / V不下","f":["Động từ + 得了 / 不了 — làm được / không làm được (nói chung)","Động từ + 得下 / 不下 — đủ / không đủ chỗ chứa"],"note":"了 đọc liǎo, nghĩa là “nổi, được”. 下 chỉ không gian có chứa được hay không.","ex":[["她有事，明天去不了。","Cô ấy có việc, mai không đi được."],["这么多菜，我们吃得了吗？","Nhiều món thế này, mình ăn hết nổi không?"],["这个剧场坐得下一千人。","Nhà hát này ngồi được một nghìn người."],["箱子太小，放不下。","Vali nhỏ quá, không bỏ vừa."]],"warn":["Cấm hoặc khuyên ngăn thì dùng 不能, không dùng bổ ngữ khả năng: 那儿太危险，你不能去."]},{"title":"Phân biệt 能 / 不能 và bổ ngữ khả năng · vị trí tân ngữ","f":["Có điều kiện, có khả năng: 能去 = 去得了 (dùng cái nào cũng được)","Cấm, khuyên ngăn: chỉ dùng 不能 + V (不能拿、不能去)","Không đủ điều kiện, không làm nổi: chỉ dùng V不… (拿不了、看不见)","Tân ngữ: đặt sau bổ ngữ hoặc đưa lên đầu câu, không chen vào giữa"],"note":"Đây là phần đề hay ra câu sửa sai. Khi lý do là khách quan (đồ nhiều quá, tối quá, nhanh quá) thì dùng bổ ngữ khả năng ở dạng phủ định.","ex":[["东西太多了，你拿不了。","Đồ nhiều quá, bạn xách không nổi đâu."],["屋子里太黑，我看不见。","Trong phòng tối quá, tôi không nhìn thấy."],["这东西不是你的，你不能拿。","Đồ này không phải của bạn, bạn không được lấy."],["你看得懂看不懂中文小说儿？","Bạn đọc hiểu tiểu thuyết tiếng Trung không?"]],"warn":["Sai: *我不能听懂* → 我听不懂; *你把中文小说儿看得懂看不懂* → 你看得懂看不懂中文小说儿.","Sai: *吃得完吃得不完* → 吃得完吃不完; *放得不下* → 放不下."]}]},{"n":21,"zh":"山这么高，你爬得上去吗","vi":"Núi cao thế này, anh có leo lên được không?","texts":[{"zh":"（一）山这么高，你爬得上去吗","vi":"Núi cao thế này, anh có leo lên được không?","phu":false,"pairs":[["林老师：王老师，咱们怎么上山？坐缆车上去还是爬上去？","Cô Lâm: Thầy Vương, chúng ta lên núi bằng cách nào? Đi cáp treo hay leo lên?"],["王老师：别坐缆车了。跟同学们一起爬上去吧。","Thầy Vương: Đừng đi cáp treo nữa. Cùng các bạn leo lên đi."],["林老师：山这么高，你爬得上去吗？","Cô Lâm: Núi cao thế này, anh leo lên được không?"],["王老师：没问题。爬得上去。","Thầy Vương: Không vấn đề gì. Leo lên được."],["林老师：美英，我看你累得都喘不上气来了，还爬得动吗？","Cô Lâm: Mỹ Anh, cô thấy em mệt đến thở không ra hơi rồi, còn leo nổi không?"],["李美英：爬得动。","Lý Mỹ Anh: Leo nổi ạ."],["林老师：别着急，一步一步地往上爬，爬不动的时候就休息一会儿。走，咱们一起爬，要坚持到底，坚持就是胜利。……王老师，加油儿啊！","Cô Lâm: Đừng vội, leo từng bước một, lúc nào leo không nổi thì nghỉ một lát. Đi nào, chúng ta cùng leo, phải kiên trì đến cùng, kiên trì là thắng lợi. … Thầy Vương, cố lên nhé!"],["王老师：刚爬一会儿就出了一身汗，我休息一会儿再接着爬，比不了你们年轻人啦。","Thầy Vương: Mới leo một lúc đã toát cả mồ hôi, tôi nghỉ một lát rồi leo tiếp, không so được với các bạn trẻ đâu."],["李美英：啊，看，王老师也爬上来了。","Lý Mỹ Anh: A, nhìn kìa, thầy Vương cũng leo lên rồi."],["王老师：麦克，别从那儿上，太危险了。要注意安全。","Thầy Vương: Mike, đừng leo lên từ chỗ đó, nguy hiểm lắm. Phải chú ý an toàn."],["麦克：知道了。","Mike: Em biết rồi ạ."]]},{"zh":"（二）我担心自己演不好","vi":"Tôi lo mình diễn không tốt","phu":false,"pairs":[["林老师：爱德华，咱们班参加联欢会的节目准备得怎么样了？","Cô Lâm: Edward, tiết mục của lớp mình tham gia liên hoan chuẩn bị đến đâu rồi?"],["爱德华：大家都在积极地准备呢。","Edward: Mọi người đều đang tích cực chuẩn bị ạ."],["林老师：你表演什么节目？","Cô Lâm: Em biểu diễn tiết mục gì?"],["爱德华：我和麦克说个相声。可是我总记不住台词，正背台词呢。","Edward: Em và Mike diễn một tiết mục tấu hài. Nhưng em cứ không nhớ nổi lời thoại, đang học thuộc lời đây ạ."],["林老师：背会了吗？","Cô Lâm: Thuộc chưa?"],["爱德华：快了。山本，你们的小话剧呢？","Edward: Sắp rồi ạ. Yamamoto, vở kịch ngắn của các cậu thì sao?"],["山本：我们也正在排练呢。有的音我发不准，我请田芳一句一句地给我纠正。","Yamamoto: Bọn mình cũng đang tập. Có âm mình phát âm không chuẩn, mình nhờ Điền Phương sửa cho từng câu một."],["林老师：谁跟你一起表演？","Cô Lâm: Ai diễn cùng em?"],["山本：原来是玛丽，可是玛丽腿受伤了，参加不了了。我请罗兰跟我一起表演。","Yamamoto: Lúc đầu là Mary, nhưng Mary bị thương ở chân, không tham gia được nữa. Em nhờ Roland diễn cùng em."],["罗兰：我担心自己演不好。","Roland: Mình lo mình diễn không tốt."],["林老师：要有自信，相信自己能演好。","Cô Lâm: Phải tự tin, tin rằng mình có thể diễn tốt."],["山本：只要我们好好儿练，就一定能演好。“世上无难事，只怕有心人”嘛！","Yamamoto: Chỉ cần chúng mình tập luyện chăm chỉ thì nhất định sẽ diễn tốt. “Trên đời không có việc gì khó, chỉ sợ lòng không bền” mà!"],["罗兰：我一定努力，争取演出成功。","Roland: Mình nhất định cố gắng, phấn đấu biểu diễn thành công."],["山本：老师，您也给我们表演个节目吧。","Yamamoto: Cô ơi, cô cũng biểu diễn cho chúng em một tiết mục đi ạ."],["林老师：我准备了一首歌，不过，很长时间没唱了，恐怕唱不好。","Cô Lâm: Cô chuẩn bị một bài hát, nhưng lâu lắm rồi không hát, e là hát không hay."],["山本：老师，这个地方这么小，坐得下二百多人吗？","Yamamoto: Cô ơi, chỗ này nhỏ thế, có chứa nổi hơn hai trăm người không ạ?"],["林老师：联欢会在楼下小礼堂举行，那儿能坐下三四百人呢。","Cô Lâm: Buổi liên hoan tổ chức ở hội trường nhỏ dưới tầng, chỗ đó ngồi được ba bốn trăm người đấy."]]},{"zh":"（读后复述）画蛇添足","vi":"Vẽ rắn thêm chân","phu":true,"pairs":[["从前，有几个人得到了一壶酒。他们谁都想喝这壶酒，可是这壶酒只够一个人喝，给谁喝呢，半天决定不了。一个人说：“这样吧，我们每个人都在地上画一条蛇。谁先画完，这壶酒就给谁喝。”大家都同意他的办法，于是就在地上画了起来。","Ngày xưa, có mấy người được một bình rượu. Ai cũng muốn uống bình rượu này, nhưng bình rượu chỉ đủ cho một người uống, cho ai uống đây, bàn mãi không quyết được. Một người nói: “Thế này nhé, mỗi người chúng ta vẽ một con rắn trên mặt đất. Ai vẽ xong trước thì bình rượu này thuộc về người đó.” Mọi người đều đồng ý cách của anh ta, thế là bắt đầu vẽ trên mặt đất."],["有一个人很快把蛇画好了。他看别人还都没有画完，就左手拿起酒壶，右手又画起来，还得意地说：“你们画得太慢了！你们看我，还能给蛇添上几只脚呢。”","Có một người vẽ xong con rắn rất nhanh. Anh ta thấy những người khác đều chưa vẽ xong, bèn tay trái cầm bình rượu lên, tay phải lại vẽ tiếp, còn đắc ý nói: “Các anh vẽ chậm quá! Xem tôi này, còn có thể vẽ thêm mấy cái chân cho con rắn nữa.”"],["当他正在给蛇画脚的时候，另一个人也把蛇画好了，就把酒壶拿了过去，说：“蛇是没有脚的，你给它画上了脚，就不是蛇了。所以，第一个画完蛇的是我，不是你！”说完就把酒喝了。","Khi anh ta đang vẽ chân cho rắn thì một người khác cũng vẽ xong con rắn, liền giật lấy bình rượu, nói: “Rắn làm gì có chân, anh vẽ chân cho nó thì nó không còn là rắn nữa. Cho nên người vẽ xong rắn đầu tiên là tôi, không phải anh!” Nói xong liền uống hết rượu."]]}],"grammar":[{"title":"Bổ ngữ khả năng (2) — 动 · 住 · 好","f":["Động từ + 得动 / 不动 — có sức / không có sức làm","Động từ + 得住 / 不住 — giữ được, nhớ được / không","Động từ + 得好 / 不好 — làm tốt được / không"],"note":"Ba bổ ngữ hay gặp: 动 nói về sức lực, 住 nói về sự chắc chắn, giữ lại, 好 nói về chất lượng hoàn thành.","ex":[["山这么高，你爬得上去吗？","Núi cao thế, bạn leo lên được không?"],["这个箱子太重了，我搬不动。","Cái thùng này nặng quá, tôi khiêng không nổi."],["台词太长，我总记不住。","Lời thoại dài quá, tôi cứ không nhớ nổi."],["我担心自己演不好。","Tôi lo mình diễn không tốt."]],"warn":[]},{"title":"只要…就… — chỉ cần… là…","f":["只要 + điều kiện, (Chủ ngữ) + 就 + kết quả"],"note":"Nêu điều kiện đủ: chỉ cần có điều kiện đó là có kết quả.","ex":[["只要我们好好儿练，就一定能演好。","Chỉ cần mình tập kỹ là nhất định diễn tốt."],["只要有时间，我就去看你。","Chỉ cần có thời gian là tôi đi thăm bạn."]],"warn":[]},{"title":"Phân biệt bổ ngữ khả năng và bổ ngữ trạng thái","f":["Khả năng: 演得好 / 演不好 — hỏi: 演得好演不好？","Trạng thái: 演得好 / 演得不好 — hỏi: 演得好不好？"],"note":"Khẳng định giống nhau (演得好) nhưng nghĩa khác: khả năng nói chuyện có làm được hay không (thường là việc chưa làm), trạng thái là đánh giá việc đã làm. Bổ ngữ khả năng mang được tân ngữ phía sau, bổ ngữ trạng thái thì không.","ex":[["我担心自己演不好这个节目。","Tôi lo mình không diễn tốt được tiết mục này. (khả năng)"],["这个节目他演得不好。","Tiết mục này anh ấy diễn không hay. (trạng thái)"],["这个书架我们两个搬不动。","Cái kệ sách này hai đứa mình khiêng không nổi."]],"warn":["Sai: *我演得不好这个节目* → 这个节目我演得不好. Sai: *搬得不进去* → 搬不进去; *见面得了吗* → 见得了面吗."]}]},{"n":22,"zh":"我想起来了","vi":"Tôi nhớ ra rồi","texts":[{"zh":"（一）我想起来了","vi":"Tôi nhớ ra rồi","phu":false,"pairs":[["海伦：喂，是王老师吗？","Helen: A lô, có phải thầy Vương không ạ?"],["王老师：是。你是……","Thầy Vương: Đúng. Em là…"],["海伦：老师，您听得出来我是谁吗？","Helen: Thầy ơi, thầy có nghe ra em là ai không?"],["王老师：你是……对不起，声音有点儿熟，但一下子想不起来是谁了。","Thầy Vương: Em là… Xin lỗi, giọng nghe hơi quen, nhưng nhất thời không nhớ ra là ai."],["海伦：我是您三年前的学生，您还参加过我的婚礼呢。","Helen: Em là học trò của thầy ba năm trước, thầy còn dự đám cưới của em nữa đấy ạ."],["王老师：啊，我想起来了，海伦！你现在在哪儿？","Thầy Vương: À, thầy nhớ ra rồi, Helen! Bây giờ em ở đâu?"],["海伦：我就在北京。","Helen: Em đang ở Bắc Kinh ạ."],["王老师：你是怎么知道这个电话号码的？","Thầy Vương: Sao em biết số điện thoại này?"],["海伦：是罗兰告诉我的。","Helen: Là Roland cho em biết ạ."],["王老师：是吗？你是来旅行的吗？","Thầy Vương: Thế à? Em đến du lịch à?"],["海伦：不是。我是应国际广播电台的邀请来北京工作的。","Helen: Không ạ. Em nhận lời mời của Đài Phát thanh Quốc tế đến Bắc Kinh làm việc."],["王老师：要待多长时间？","Thầy Vương: Định ở lại bao lâu?"],["海伦：我跟他们签了两年的合同。","Helen: Em ký hợp đồng hai năm với họ ạ."],["王老师：保罗呢？","Thầy Vương: Còn Paul thì sao?"],["海伦：保罗也来了。他在北京的一家中外合资公司工作。老师，我们想请您来我家做客。","Helen: Paul cũng sang rồi ạ. Anh ấy làm việc ở một công ty liên doanh Trung – nước ngoài tại Bắc Kinh. Thầy ơi, chúng em muốn mời thầy đến nhà chơi."],["王老师：好啊。","Thầy Vương: Được thôi."],["海伦：不知道您星期六下午有没有空儿？","Helen: Không biết chiều thứ Bảy thầy có rảnh không ạ?"],["王老师：这个星期六下午可以。","Thầy Vương: Chiều thứ Bảy tuần này thì được."],["海伦：那我让保罗开车去接您。您还住在原来的地方吗？","Helen: Vậy em bảo Paul lái xe đến đón thầy. Thầy vẫn ở chỗ cũ chứ ạ?"],["王老师：不，我早就搬家了，搬到学校附近一个新建的住宅小区了。我告诉你，你把我的地址记下来。保罗来的时候，给我来个电话，我去门口接他。","Thầy Vương: Không, thầy chuyển nhà lâu rồi, chuyển đến một khu dân cư mới xây gần trường. Thầy nói em nghe, em ghi lại địa chỉ của thầy nhé. Khi Paul đến thì gọi cho thầy một cuộc, thầy ra cổng đón cậu ấy."],["海伦：好的。","Helen: Vâng ạ."]]},{"zh":"（二）我们还想学下去","vi":"Chúng em còn muốn học tiếp","phu":false,"pairs":[["海伦：老师，您喝点儿什么？茶还是咖啡？","Helen: Thầy ơi, thầy uống gì ạ? Trà hay cà phê?"],["王老师：我茶和咖啡都喝不了，一喝晚上就睡不着觉。就喝点儿水吧。你们这儿真不错！","Thầy Vương: Trà và cà phê thầy đều không uống được, hễ uống là tối mất ngủ. Uống chút nước thôi. Chỗ các em đẹp thật!"],["海伦：这是保罗的公司给我们租的房子。要是让我们自己花钱可租不起。","Helen: Đây là nhà công ty của Paul thuê cho chúng em. Nếu để chúng em tự bỏ tiền thì không thuê nổi đâu ạ."],["王老师：保罗，你们公司的业务是什么？","Thầy Vương: Paul, công ty em làm mảng gì?"],["保罗：我们公司是搞中外文化交流的。公司成立不久，业务也刚开展起来。","Paul: Công ty em làm về giao lưu văn hóa Trung – nước ngoài. Công ty mới thành lập chưa lâu, công việc cũng vừa bắt đầu triển khai."],["海伦：老师，我和保罗的工作都需要用汉语，所以打算继续学下去。我们想利用在北京工作的机会把汉语学好。","Helen: Thầy ơi, công việc của em và Paul đều cần dùng tiếng Hán, nên chúng em định tiếp tục học. Chúng em muốn tận dụng cơ hội làm việc ở Bắc Kinh để học giỏi tiếng Hán."],["王老师：你们俩原来都学得不错，有一定的基础，坚持学下去的话，一定能学好。","Thầy Vương: Hai em trước đây đều học khá, có nền tảng nhất định, nếu kiên trì học tiếp thì nhất định sẽ học giỏi."],["海伦：时间过得真快！离开中国都三年多了。刚回国的时候，还常听听录音，读读课文。后来因为忙，也没坚持下来。很长时间不说，汉语差不多都忘光了，要用的时候，好多词都想不起来了。","Helen: Thời gian trôi nhanh thật! Rời Trung Quốc đã hơn ba năm rồi. Hồi mới về nước, em vẫn thường nghe băng, đọc bài khóa. Sau này vì bận nên cũng không duy trì được. Lâu không nói, tiếng Hán gần như quên sạch, lúc cần dùng thì rất nhiều từ không nhớ ra nữa."],["王老师：是。学外语，只有坚持下去，多听、多说、多练才能学好。","Thầy Vương: Đúng vậy. Học ngoại ngữ, chỉ có kiên trì, nghe nhiều, nói nhiều, luyện nhiều mới học giỏi được."],["海伦：我们还想请老师业余教我们，不知道老师能不能抽出时间来。","Helen: Chúng em còn muốn nhờ thầy dạy thêm ngoài giờ, không biết thầy có thu xếp được thời gian không ạ."],["王老师：我工作比较忙，抽不出时间来。你们打算怎么学？","Thầy Vương: Thầy công việc khá bận, không thu xếp được thời gian. Các em định học thế nào?"],["海伦：白天我们都没有时间，只有晚上才抽得出时间。要是老师同意的话，我们想到老师家里去上课。","Helen: Ban ngày chúng em đều không có thời gian, chỉ có buổi tối mới thu xếp được. Nếu thầy đồng ý, chúng em muốn đến nhà thầy học ạ."]]},{"zh":"（综合填空）司马光砸缸","vi":"Tư Mã Quang đập chum","phu":true,"pairs":[["这是一个中国古时候的故事。有一天，司马光和小朋友们在院子里玩儿。院子里有个大水缸，水缸里装满了水。他们玩儿得正高兴的时候，一个小朋友不小心掉到水缸里去了。","Đây là một câu chuyện thời xưa của Trung Quốc. Một hôm, Tư Mã Quang chơi đùa cùng các bạn nhỏ trong sân. Trong sân có một cái chum nước lớn, chum đựng đầy nước. Đang chơi vui vẻ thì một bạn nhỏ không cẩn thận rơi xuống chum nước."],["一个孩子看见了，就大声喊了起来：“救人啊！救人啊！有人掉到水缸里去了。”有的孩子吓得哭了起来。水缸很大，不容易从上面救人。","Một đứa trẻ nhìn thấy liền hét to: “Cứu người với! Cứu người với! Có người rơi xuống chum nước rồi.” Có đứa sợ quá òa khóc. Chum nước rất to, khó mà cứu người từ phía trên."],["司马光看到这种情况，很快想出来了一个好办法。他连忙搬起一块石头，跑了过来，向水缸砸去，一下子就把水缸砸破了。水缸里的水都流了出来。掉在水缸里的小朋友得救了。看到从水缸里爬出来的小朋友，大家都笑了起来。","Tư Mã Quang thấy tình hình như vậy, rất nhanh đã nghĩ ra một cách hay. Cậu vội vàng bê một hòn đá chạy tới, ném mạnh vào chum nước, chỉ một cái là chum vỡ. Nước trong chum chảy hết ra ngoài. Bạn nhỏ rơi trong chum được cứu. Nhìn thấy bạn nhỏ bò ra từ trong chum, mọi người đều bật cười."]]}],"grammar":[{"title":"Động từ + 起来 — bắt đầu / nhớ ra / đánh giá","f":["Động từ + 起来 — bắt đầu và tiếp diễn (笑起来、哭起来)","Động từ + 起 + Tân ngữ + 来 — có tân ngữ thì chen giữa (下起雨来)","想起来 — nhớ ra điều đã biết mà quên","看起来 / 听起来 — nhìn thì / nghe thì (đánh giá)"],"note":"起来 cho biết động tác bắt đầu và kéo dài. Có tân ngữ thì đặt giữa 起 và 来.","ex":[["她说得大家都笑起来了。","Cô ấy nói làm mọi người bật cười."],["刚才还是晴天，突然下起雨来了。","Vừa nãy còn nắng, đột nhiên trời đổ mưa."],["我想起来了，你是海伦！","Tôi nhớ ra rồi, bạn là Helen!"],["这件衣服看起来很贵。","Cái áo này nhìn có vẻ đắt."]],"warn":["Sai: *下雨起来* → Đúng: 下起雨来."]},{"title":"Động từ + 出来 — nhận ra / làm ra cái mới","f":["看出来 / 听出来 / 认出来 — nhận ra, phân biệt ra","想出来 / 做出来 / 写出来 — làm ra cái từ không thành có"],"note":"出来 cho biết cái gì đó từ ẩn thành lộ (nhận ra) hoặc từ không thành có (nghĩ ra, làm ra).","ex":[["我听出来了，这是小王的声音。","Tôi nghe ra rồi, đây là giọng Tiểu Vương."],["我看出来了，这是王老师写的字。","Tôi nhận ra rồi, đây là chữ thầy Vương viết."],["他想出来一个好办法。","Anh ấy nghĩ ra một cách hay."],["这道题我做出来了。","Bài này tôi giải ra rồi."],["你喝出来了吗，这是什么茶？","Bạn uống có nhận ra đây là trà gì không?"]],"warn":["想起来 = nhớ ra cái đã biết mà quên; 想出来 = nghĩ ra cái mới (办法、主意). 我也想不出好办法来.","Sai: *他照起来的照片* → 照出来的照片; *想不出来她叫什么名字* → 想不起来."]},{"title":"Động từ + 下去 — tiếp tục làm","f":["Động từ + 下去 — việc đang làm thì làm tiếp (từ nay về sau)"],"note":"下去 nhìn về phía sau: hành động đang diễn ra sẽ tiếp tục kéo dài.","ex":[["汉语很有意思，我想学下去。","Tiếng Hán rất thú vị, tôi muốn học tiếp."],["明年，我还想继续在这儿学下去。","Năm sau tôi vẫn muốn tiếp tục học ở đây."],["你说下去，我听着呢。","Bạn nói tiếp đi, tôi đang nghe đây."]],"warn":[]},{"title":"Động từ + 下来 — ghi lại, giữ lại / kéo dài đến nay / dừng lại","f":["记下来 / 写下来 / 照下来 / 录下来 — cố định lại, lưu lại","坚持下来 / 留下来 / 活下来 — từ trước kéo dài đến bây giờ","停下来 / 安静下来 / 冷静下来 — từ động chuyển sang tĩnh"],"note":"下来 nhìn từ quá khứ đến hiện tại: giữ lại kết quả, duy trì được đến nay, hoặc chuyển sang trạng thái yên, dừng.","ex":[["我已经把他的地址和电话号码记下来了。","Tôi đã ghi lại địa chỉ và số điện thoại của anh ấy."],["这么漂亮的风景，快照下来吧。","Cảnh đẹp thế này, chụp lại mau đi."],["后来因为忙，我没有坚持下来。","Sau đó vì bận nên tôi không duy trì được."],["车停下来了。","Xe dừng lại rồi."],["孩子睡了，家里安静下来了。","Con ngủ rồi, nhà yên tĩnh lại."]],"warn":["Phân biệt: 下去 = từ bây giờ làm tiếp về sau; 下来 = từ trước kéo dài đến bây giờ."]},{"title":"只有…才… · Động từ + 不起","f":["只有 + điều kiện duy nhất, (Chủ ngữ) + 才 + kết quả","Động từ + 不起 — không đủ tiền / điều kiện để làm"],"note":"只有…才 nhấn mạnh điều kiện bắt buộc (khác 只要…就 là điều kiện đủ). V不起 hay gặp: 买不起、租不起、住不起.","ex":[["只有坚持下去，才能学好汉语。","Chỉ có kiên trì mới học giỏi tiếng Hán được."],["只有你去，他才会来。","Chỉ khi bạn đi thì anh ấy mới đến."],["这么贵的房子，我们租不起。","Nhà đắt thế này, mình thuê không nổi."]],"warn":["Phải đúng cặp: 只要…就, 只有…才. *只要…才* là sai."]}]},{"n":23,"zh":"寒假你打算去哪儿旅行","vi":"Kỳ nghỉ đông bạn định đi du lịch đâu?","texts":[{"zh":"（一）吃什么都可以","vi":"Ăn gì cũng được","phu":false,"pairs":[["麦克：我有点儿饿了，想吃点儿什么。你呢？","Mike: Mình hơi đói rồi, muốn ăn chút gì đó. Còn cậu?"],["玛丽：我也又饿又渴。咱们去饭馆儿吧。","Mary: Mình cũng vừa đói vừa khát. Chúng ta đi nhà hàng đi."],["麦克：你想吃点儿什么？","Mike: Cậu muốn ăn gì?"],["玛丽：你点吧，什么都可以。","Mary: Cậu gọi đi, gì cũng được."],["麦克：那就什么好吃吃什么。","Mike: Vậy món nào ngon thì ăn món đó."],["服务员：你们两位要点儿什么？","Phục vụ: Hai vị muốn gọi gì ạ?"],["麦克：服务员，你们这儿有什么好吃的菜？","Mike: Phục vụ ơi, ở đây có món gì ngon?"],["服务员：我们这儿什么菜都好吃啊。","Phục vụ: Ở chỗ chúng tôi món nào cũng ngon ạ."],["麦克：是吗？那把你们这儿最好吃的菜给我们来两个。","Mike: Thế à? Vậy cho chúng tôi hai món ngon nhất ở đây."],["服务员：这儿的辣子鸡丁和糖醋鱼都不错。","Phục vụ: Gà xào ớt và cá sốt chua ngọt ở đây đều ngon ạ."],["麦克：那就一样来一个吧。我们喝点儿什么呢？","Mike: Vậy mỗi món cho một đĩa. Chúng ta uống gì nhỉ?"],["玛丽：随便。你说喝什么就喝什么吧。","Mary: Tùy cậu. Cậu bảo uống gì thì uống nấy."]]},{"zh":"（二）你是哪儿冷去哪儿啊","vi":"Cậu đúng là chỗ nào lạnh thì đi chỗ đó nhỉ","phu":false,"pairs":[["田中：时间过得真快，下周考完试就要放寒假了。","Tanaka: Thời gian trôi nhanh thật, tuần sau thi xong là được nghỉ đông rồi."],["麦克：是啊。寒假你有什么打算吗？","Mike: Đúng vậy. Nghỉ đông cậu có dự định gì không?"],["田中：学校要组织留学生去外地旅行，谁都可以报名，你报名吗？","Tanaka: Trường sẽ tổ chức cho lưu học sinh đi du lịch tỉnh ngoài, ai cũng có thể đăng ký, cậu có đăng ký không?"],["麦克：我听谁说过这件事儿。不过我想自己去旅行。","Mike: Mình có nghe ai đó nói về chuyện này. Nhưng mình muốn tự đi du lịch."],["田中：去哪儿？","Tanaka: Đi đâu?"],["麦克：哪儿好玩儿就去哪儿。我想去哈尔滨。","Mike: Chỗ nào vui thì đi chỗ đó. Mình muốn đi Cáp Nhĩ Tân."],["田中：哈尔滨？你是哪儿冷去哪儿啊。现在那儿白天已经零下二十多度了。","Tanaka: Cáp Nhĩ Tân? Cậu đúng là chỗ nào lạnh thì đi chỗ đó nhỉ. Bây giờ ban ngày ở đó đã âm hơn hai mươi độ rồi."],["麦克：听说哈尔滨的冰灯冰雕很好看，我想去看看。","Mike: Nghe nói đèn băng, tượng băng ở Cáp Nhĩ Tân rất đẹp, mình muốn đi xem."],["田中：你想怎么去？","Tanaka: Cậu định đi bằng gì?"],["麦克：除了骑自行车以外，怎么去都行。","Mike: Ngoài đi xe đạp ra thì đi bằng gì cũng được."],["田中：你又开玩笑。","Tanaka: Cậu lại đùa rồi."],["麦克：要是买不到火车票就坐飞机去。你的计划呢？","Mike: Nếu không mua được vé tàu thì đi máy bay. Kế hoạch của cậu thì sao?"],["田中：我打算先去西安看看碑林和兵马俑，再到重庆，从重庆坐船游览长江三峡，然后去云南、桂林，最后去苏州和杭州。","Tanaka: Mình định trước tiên đi Tây An xem Bi Lâm và tượng binh mã, rồi đến Trùng Khánh, từ Trùng Khánh đi thuyền ngắm Tam Hiệp Trường Giang, sau đó đi Vân Nam, Quế Lâm, cuối cùng đi Tô Châu và Hàng Châu."],["麦克：田芳说，苏州、杭州很美。","Mike: Điền Phương nói Tô Châu, Hàng Châu rất đẹp."],["田中：“上有天堂，下有苏杭”嘛。另外，桂林也不错，“桂林山水甲天下”，风景像画儿一样，美极了。你去过桂林吗？","Tanaka: “Trên có thiên đường, dưới có Tô Hàng” mà. Ngoài ra, Quế Lâm cũng đẹp, “Sơn thủy Quế Lâm đẹp nhất thiên hạ”, phong cảnh như tranh vẽ, đẹp tuyệt. Cậu đi Quế Lâm bao giờ chưa?"],["麦克：没有。我对云南少数民族的风俗很感兴趣。要是有机会一定去看看。你的旅行路线很好，不过要花多少钱啊？","Mike: Chưa. Mình rất hứng thú với phong tục của các dân tộc thiểu số ở Vân Nam. Nếu có cơ hội nhất định sẽ đi xem. Lộ trình du lịch của cậu rất hay, nhưng phải tốn bao nhiêu tiền đây?"],["田中：我喜欢旅行，只要玩儿得开心，多花点儿钱也值得。另外最重要的是还可以一边旅行一边练习说汉语，多有意义啊！","Tanaka: Mình thích du lịch, chỉ cần chơi vui thì tốn thêm chút tiền cũng đáng. Ngoài ra quan trọng nhất là còn có thể vừa du lịch vừa luyện nói tiếng Hán, ý nghĩa biết bao!"],["麦克：你说得对。","Mike: Cậu nói đúng."]]},{"zh":"（读后复述）吃药吃的","vi":"Tại uống thuốc mà ra","phu":true,"pairs":[["因为吃得好也吃得多，我越来越胖。天冷了，为了减肥，我决定去游泳。那天，我去奥林匹克体育中心游泳馆游了一会儿泳，第二天头就疼起来了。我到医院去看病。大夫说我感冒了，开了一些药让我吃。吃了感冒药就想睡觉。","Vì ăn ngon lại ăn nhiều nên tôi càng ngày càng béo. Trời lạnh rồi, để giảm cân tôi quyết định đi bơi. Hôm đó, tôi đến bể bơi Trung tâm Thể thao Olympic bơi một lúc, hôm sau liền bắt đầu đau đầu. Tôi đến bệnh viện khám. Bác sĩ nói tôi bị cảm, kê ít thuốc cho tôi uống. Uống thuốc cảm xong thì chỉ muốn ngủ."],["睡了两天以后，头不疼了，但是嗓子却疼起来了。大夫说，天气太干燥，又让我吃药。过了三天，嗓子不疼了，又咳嗽起来了，而且越咳越厉害，咳得晚上睡不着觉。大夫看了以后给我开了一些咳嗽药。没想到，当天晚上我就发起烧来了。大夫只好又给我开退烧药。他说这药很好，但是要多喝水。","Ngủ hai ngày, đầu hết đau nhưng họng lại bắt đầu đau. Bác sĩ nói thời tiết hanh khô quá, lại bắt tôi uống thuốc. Ba ngày sau, họng hết đau thì lại bắt đầu ho, mà càng ho càng nặng, ho đến mức tối không ngủ được. Bác sĩ khám xong kê cho tôi ít thuốc ho. Không ngờ ngay tối hôm đó tôi lại bắt đầu sốt. Bác sĩ đành kê thêm thuốc hạ sốt. Ông ấy nói thuốc này rất tốt nhưng phải uống nhiều nước."],["药真的很好，很快就不发烧了。但是好几天没有大便了。大夫一检查说我大便干燥。这次，大夫说吃点儿中药吧。中药也很好，吃了以后，第二天就有了要大便的感觉，连忙去厕所，没想到又拉起肚子来了。去找大夫，他说我把肚子吃坏了，再开点儿治肚子的药吃吃吧。","Thuốc đúng là tốt thật, rất nhanh đã hết sốt. Nhưng mấy ngày liền không đi đại tiện được. Bác sĩ khám rồi nói tôi bị táo bón. Lần này bác sĩ bảo uống chút thuốc Bắc. Thuốc Bắc cũng rất tốt, uống xong, hôm sau đã thấy buồn đi ngoài, vội vàng vào nhà vệ sinh, không ngờ lại bắt đầu tiêu chảy. Đi tìm bác sĩ, ông ấy nói tôi ăn uống làm hỏng bụng rồi, kê thêm ít thuốc chữa bụng mà uống."],["昨天下午，一位当医生的朋友来看我。他说：“你的脸色怎么这么难看，我给你开点儿药吃吃吧。”我说：“不用了。我这难看的脸色都是吃药吃的。”","Chiều hôm qua, một người bạn làm bác sĩ đến thăm tôi. Anh ấy nói: “Sắc mặt cậu sao khó coi thế, để mình kê ít thuốc cho cậu uống nhé.” Tôi nói: “Thôi khỏi. Cái sắc mặt khó coi này của mình toàn là do uống thuốc mà ra đấy.”"],["他好像听不懂我的话，我就把这些天看病的经过跟他说了说。他听了以后大笑起来，对我说：“是，是，你不能再吃药了。不过，应该去运动运动。冬天太冷，到外边运动容易感冒，到奥体中心去游游泳吧。”我一听他的话，头又立刻疼了起来。","Anh ấy hình như không hiểu tôi nói gì, tôi bèn kể cho anh ấy nghe quá trình đi khám bệnh mấy hôm nay. Nghe xong anh ấy cười phá lên, nói với tôi: “Ừ, ừ, cậu không được uống thuốc nữa. Nhưng mà nên đi vận động một chút. Mùa đông lạnh quá, ra ngoài vận động dễ bị cảm, đến trung tâm Olympic bơi đi.” Tôi vừa nghe anh ấy nói vậy, đầu lại lập tức đau trở lại."]]}],"grammar":[{"title":"Đại từ nghi vấn chỉ “bất cứ” (任指)","f":["什么 / 谁 / 哪儿 / 怎么 / 什么时候 + 都 / 也 + …"],"note":"Chỉ bất cứ người, vật, nơi, cách nào, không có ngoại lệ. Phía sau luôn có 都 hoặc 也 (phủ định hay dùng 也).","ex":[["吃什么都可以。","Ăn gì cũng được."],["这儿什么菜都好吃。","Ở đây món nào cũng ngon."],["谁都可以报名。","Ai cũng có thể đăng ký."],["周末我哪儿也不想去。","Cuối tuần tôi không muốn đi đâu cả."],["什么时候来都欢迎。","Lúc nào đến cũng hoan nghênh."]],"warn":["Sai: *我的电脑坏了，什么也修不好* → 怎么也修不好; *什么汉语不会说* → 什么汉语都不会说."]},{"title":"Đại từ nghi vấn hô ứng (特指) — … nào … nấy","f":["Đại từ nghi vấn … (就) … cùng đại từ nghi vấn đó","哪儿好玩儿就去哪儿 · 什么好吃就吃什么 · 谁说得好就跟谁学"],"note":"Một câu dùng 2 lần cùng một đại từ nghi vấn, cả hai chỉ cùng một đối tượng. 就 đặt sau chủ ngữ của vế sau.","ex":[["哪儿好玩儿就去哪儿。","Chỗ nào vui thì đi chỗ đó."],["你说喝什么就喝什么吧。","Bạn bảo uống gì thì uống nấy."],["谁说得好，我们就跟谁学。","Ai nói giỏi thì mình học theo người đó."],["你是哪儿冷去哪儿啊。","Bạn đúng là chỗ nào lạnh thì đi chỗ đó."]],"warn":["Phải dùng cùng một đại từ: *哪个题容易，我就做什么题* → 哪个题容易，我就做哪个题.","Sai: *哪儿好玩儿，就我们去哪儿* → 我们就去哪儿; *你说怎么，我就做怎么* → 你说怎么做，我就怎么做."]},{"title":"Đại từ nghi vấn phiếm chỉ (虚指) — ai đó, cái gì đó, đâu đó","f":["谁 = ai đó · 什么 = cái gì đó · 哪儿 = đâu đó · 怎么 = sao đó"],"note":"Chỉ một người/vật/nơi không rõ hoặc không cần nói rõ. Câu không phải câu hỏi.","ex":[["我听谁说过这件事儿。","Tôi nghe ai đó nói chuyện này rồi."],["我想买点儿什么礼物。","Tôi muốn mua chút quà gì đó."],["我好像在哪儿见过他。","Hình như tôi gặp anh ấy ở đâu rồi."],["手机不知怎么弄坏了。","Điện thoại không biết sao lại bị hỏng."]],"warn":[]},{"title":"一边…一边… — vừa… vừa…","f":["一边 + V1 + 一边 + V2","Động từ đơn âm tiết có thể bỏ 一: 边听边看"],"note":"Hai hành động diễn ra cùng lúc. Cả hai phải là hành động làm được song song, không dùng với động từ chỉ cảm giác, trạng thái.","ex":[["我想一边旅行一边练习说汉语。","Tôi muốn vừa du lịch vừa luyện nói tiếng Hán."],["她一边听音乐一边做饭。","Cô ấy vừa nghe nhạc vừa nấu cơm."],["我们边吃边谈吧。","Mình vừa ăn vừa nói chuyện nhé."]],"warn":["Sai: *我一边打篮球一边觉得很饿*; *老师的话我一边听一边不懂* (觉得、不懂 không phải hành động)."]},{"title":"先…再…然后…最后… — trình tự các việc","f":["先 + V1，再 (又) + V2，然后 + V3，最后 + V4"],"note":"Sắp xếp các việc theo thứ tự trước sau, hay dùng khi kể kế hoạch, lịch trình.","ex":[["先去西安，再到重庆，然后去桂林，最后去杭州。","Trước đi Tây An, rồi Trùng Khánh, sau đó Quế Lâm, cuối cùng Hàng Châu."],["我先洗澡，然后吃饭。","Tôi tắm trước, sau đó ăn cơm."]],"warn":[]}]},{"n":24,"zh":"有困难找警察","vi":"Có khó khăn hãy tìm cảnh sát","texts":[{"zh":"（一）有困难找警察","vi":"Có khó khăn hãy tìm cảnh sát","phu":false,"pairs":[["麦克：街上到处都写着“有困难找警察”，你找过警察吗？","Mike: Ngoài đường chỗ nào cũng viết “Có khó khăn hãy tìm cảnh sát”, cậu tìm cảnh sát bao giờ chưa?"],["爱德华：没有。","Edward: Chưa."],["兰笛：昨天我在街上遇到一件事儿。","Randi: Hôm qua mình gặp một chuyện ngoài đường."],["麦克：什么事儿？","Mike: Chuyện gì?"],["兰笛：在一个十字路口儿，我看见一对老夫妻，看样子腿脚不太好。他们要过马路，但是看到来往的车那么多，等了半天，也没敢过来。这时，一个交通警察看见了，就立即跑了过去，扶着这两位老人，一步一步地走过来。看到这种情景，我非常感动。","Randi: Ở một ngã tư, mình thấy một đôi vợ chồng già, trông có vẻ chân cẳng không được tốt. Họ muốn qua đường, nhưng thấy xe cộ qua lại nhiều quá, đợi mãi cũng không dám qua. Lúc đó, một cảnh sát giao thông nhìn thấy, liền lập tức chạy tới, dìu hai ông bà từng bước một đi qua. Thấy cảnh đó, mình vô cùng cảm động."],["麦克：这是警察应该做的事儿，有什么可感动的？","Mike: Đây là việc cảnh sát nên làm, có gì mà cảm động?"],["兰笛：可是，有的地方，还发生过警察打人的事儿。","Randi: Nhưng có những nơi còn từng xảy ra chuyện cảnh sát đánh người đấy."],["爱德华：我觉得中国的警察还是不错的。我有个同学，去年秋天去重庆旅行，不小心把钱包儿和护照都丢了，身上一分钱也没有了，非常着急。正在不知道怎么办的时候，他想到“有困难找警察”这句话，就去找警察。警察为他安排了住的地方，还借给他钱买了回北京的机票，又开车把他送到机场。","Edward: Mình thấy cảnh sát Trung Quốc vẫn tốt. Mình có một người bạn, mùa thu năm ngoái đi du lịch Trùng Khánh, không cẩn thận làm mất cả ví lẫn hộ chiếu, trên người không còn một xu, vô cùng sốt ruột. Đúng lúc không biết làm thế nào thì cậu ấy nhớ đến câu “Có khó khăn hãy tìm cảnh sát”, liền đi tìm cảnh sát. Cảnh sát sắp xếp chỗ ở cho cậu ấy, còn cho cậu ấy mượn tiền mua vé máy bay về Bắc Kinh, lại lái xe đưa cậu ấy ra sân bay."],["麦克：真的吗？","Mike: Thật không?"],["爱德华：当然是真的！我还在网上看到这样一件事儿：一个四五岁的小男孩儿把球滚到大街上去了。他要跑过去拿，被警察看见了。警察就帮孩子把球捡了回来，然后把小男孩儿抱到路边。孩子说了一声“谢谢叔叔”，刚要走，又回来对警察说：“叔叔，我的鞋带儿开了。”说着就把小脚伸到警察面前，警察笑着弯下腰去，给孩子把鞋带儿系好，就像照顾自己的孩子一样。这时孩子的妈妈也跑了过来，看到这种情景，感动得不知道说什么好。","Edward: Tất nhiên là thật! Mình còn đọc trên mạng một chuyện thế này: một cậu bé bốn năm tuổi để quả bóng lăn ra giữa đường lớn. Cậu bé định chạy ra nhặt thì bị cảnh sát nhìn thấy. Cảnh sát liền nhặt bóng về giúp cậu bé, rồi bế cậu bé vào lề đường. Cậu bé nói một tiếng “Cháu cảm ơn chú”, vừa định đi thì lại quay lại nói với cảnh sát: “Chú ơi, dây giày cháu tuột rồi.” Vừa nói vừa chìa bàn chân nhỏ ra trước mặt cảnh sát, chú cảnh sát cười cúi người xuống buộc dây giày cho cậu bé, giống như chăm sóc con mình vậy. Lúc này mẹ cậu bé cũng chạy tới, thấy cảnh đó, cảm động đến mức không biết nói gì."]]},{"zh":"（二）我们把松竹梅叫作“岁寒三友”","vi":"Chúng tôi gọi tùng, trúc, mai là “Tuế hàn tam hữu”","phu":false,"pairs":[["谢大力：这幅《红梅图》画得真好！","Tạ Đại Lực: Bức “Hồng mai đồ” này vẽ đẹp thật!"],["王老师：这是一位画家朋友送的。","Thầy Vương: Đây là một người bạn họa sĩ tặng."],["谢大力：虽然是冬天，但是一看到这幅画儿就感到像春天一样。","Tạ Đại Lực: Tuy là mùa đông, nhưng vừa nhìn bức tranh này đã cảm thấy như mùa xuân vậy."],["王老师：梅、松、竹是中国画家最喜欢画的。中国人把松竹梅叫作“岁寒三友”。听说先生很喜欢中国画和中国书法。","Thầy Vương: Mai, tùng, trúc là những thứ họa sĩ Trung Quốc thích vẽ nhất. Người Trung Quốc gọi tùng, trúc, mai là “ba người bạn mùa đông giá rét”. Nghe nói ông rất thích tranh Trung Quốc và thư pháp Trung Quốc."],["谢大力：是。我每次到中国来，看到喜欢的字画，总要买一些带回去。","Tạ Đại Lực: Vâng. Mỗi lần đến Trung Quốc, thấy thư họa nào ưng ý, tôi luôn mua một ít mang về."],["王老师：我跟您一样，也非常喜欢书法和中国画。","Thầy Vương: Tôi cũng giống ông, cũng rất thích thư pháp và tranh Trung Quốc."],["谢大力：我看您的字写得很漂亮。","Tạ Đại Lực: Tôi thấy chữ ông viết rất đẹp."],["王老师：哪里。您过奖了。","Thầy Vương: Đâu có. Ông quá khen rồi."]]},{"zh":"（综合填空）十字路口儿","vi":"Ở ngã tư","phu":true,"pairs":[["天快黑了。我骑着自行车，急急忙忙地往家走。到了十字路口儿的时候，前面红灯亮了。我急忙停车，但是车没停下来，还是向前跑，我紧握车闸，还是不行，车闸坏了！我连忙往下跳，但是还是过了停车线。","Trời sắp tối. Tôi đạp xe đạp, vội vội vàng vàng về nhà. Đến ngã tư thì phía trước đèn đỏ bật lên. Tôi vội phanh xe, nhưng xe không dừng lại, vẫn lao về phía trước, tôi bóp chặt phanh, vẫn không được, phanh hỏng rồi! Tôi vội nhảy xuống, nhưng vẫn vượt qua vạch dừng."],["一个警察正站在我面前，他向我敬了个礼说：“先生，请你把自行车推到那边去。”他指了指路边的岗亭。“什么？过一点儿也要罚款？”我心里很不高兴，说：“只过这么一小点儿，我以后一定遵守交通规则，不再……”","Một cảnh sát đang đứng trước mặt tôi, anh ấy giơ tay chào tôi rồi nói: “Anh ơi, mời anh dắt xe sang bên kia.” Anh ấy chỉ vào chốt gác bên đường. “Cái gì? Vượt một chút cũng bị phạt à?” Trong lòng tôi rất không vui, nói: “Chỉ vượt có một tí xíu thôi mà, sau này tôi nhất định chấp hành luật giao thông, không bao giờ…”"],["“先生，请你过去！”他又敬了个礼，很礼貌。我只好把车推过去。他从岗亭里拿出来一个工具箱，取出一把钳子，说：“我看你的车闸坏了，所以得给你修好，大街上还有好多个十字路口儿呢！”","“Anh ơi, mời anh sang bên đó!” Anh ấy lại chào, rất lịch sự. Tôi đành dắt xe sang. Anh ấy lấy từ chốt gác ra một hộp dụng cụ, rút ra một cái kìm, nói: “Tôi thấy phanh xe của anh hỏng rồi, nên phải sửa cho anh, ngoài đường còn nhiều ngã tư lắm đấy!”"]]}],"grammar":[{"title":"Câu ghép không có từ nối (无关联词语复句)","f":["Giả thiết: Vế 1，(就) Vế 2 = 要是 … 就 …","Nhân quả: Vế 1，Vế 2 = 因为 … 所以 …"],"note":"Trong khẩu ngữ, hai vế đặt cạnh nhau, quan hệ giả thiết hay nhân quả hiểu ngầm, không cần từ nối.","ex":[["有困难找警察。","(Nếu) có khó khăn thì tìm cảnh sát."],["你去我就去。","Bạn đi thì tôi đi."],["下雨就不去了。","Mưa thì không đi nữa."],["他不小心，把护照丢了。","Anh ấy không cẩn thận nên làm mất hộ chiếu."]],"warn":["Nếu đã dùng từ nối thì phải đúng cặp: 虽然…但是, 因为…所以, 只有…才, 要是…就.","Sai: *虽然她的身体不太好，所以…* → 因为…所以; *因为她感冒了，但是还来上课* → 虽然…但是."]},{"title":"Lặp số lượng từ: 一 + lượng từ + 一 + lượng từ","f":["一步一步地 / 一个一个地 / 一口一口地 + Động từ — từng… một (trạng ngữ)","一幅一幅的 / 一件一件的 + Danh từ — từng… (định ngữ)"],"note":"Làm trạng ngữ (thêm 地) chỉ làm lần lượt, từ từ. Làm định ngữ (thêm 的) chỉ số lượng nhiều.","ex":[["警察扶着两位老人一步一步地走过来。","Cảnh sát dìu hai cụ đi từng bước một sang."],["生词要一个一个地记。","Từ mới phải nhớ từng từ một."],["饭要一口一口地吃，事要一件一件地办。","Cơm phải ăn từng miếng, việc phải làm từng việc."],["这一幅一幅的画儿都是她画的。","Từng bức tranh này đều do cô ấy vẽ."]],"warn":[]},{"title":"Bổ ngữ trạng thái (2) — … đến mức …","f":["Động từ / Tính từ + 得 + Cụm động từ / Câu nhỏ","Động từ + Tân ngữ + Động từ lặp + 得 + … (看球赛看得…)"],"note":"Sau 得 không chỉ là tính từ mà có thể là cả một cụm động từ, miêu tả mức độ hoặc kết quả.","ex":[["她感动得不知道说什么好。","Cô ấy cảm động đến mức không biết nói gì."],["孩子们高兴得跳啊唱啊。","Bọn trẻ vui đến mức vừa nhảy vừa hát."],["他看球赛看得忘了吃饭。","Anh ấy xem bóng đá đến quên cả ăn."],["她气得大叫起来。","Cô ấy tức đến mức hét lên."]],"warn":[]},{"title":"看样子 — xem ra, có vẻ","f":["看样子 + phán đoán"],"note":"Dựa vào những gì nhìn thấy để đoán. Đứng đầu câu hoặc sau chủ ngữ.","ex":[["天阴了，看样子要下雨。","Trời âm u, xem ra sắp mưa."],["看样子他们腿脚不太好。","Xem ra chân cẳng hai ông bà không được khỏe."],["他看样子像阿拉伯人。","Nhìn anh ấy có vẻ giống người Ả Rập."]],"warn":[]},{"title":"像…一样 — giống như…","f":["像 + Danh từ + 一样 (+ Tính từ / Động từ)","Làm vị ngữ, định ngữ (+的), trạng ngữ (+地), bổ ngữ (长得像…一样)"],"note":"Dùng để so sánh, ví von. Cả cụm có thể đứng nhiều vị trí trong câu.","ex":[["他照顾我就像照顾自己的孩子一样。","Anh ấy chăm tôi giống như chăm con mình vậy."],["我们像兄弟姐妹一样。","Chúng tôi như anh chị em ruột."],["她长得像她妈妈一样。","Cô ấy trông giống mẹ."],["汽车像飞一样地开了过去。","Xe chạy vụt qua như bay."]],"warn":[]}]},{"n":25,"zh":"吉利的数字","vi":"Những con số may mắn","texts":[{"zh":"（一）吉利的数字","vi":"Những con số may mắn","phu":false,"pairs":[["麦克：你知道中国人喜欢什么数字吗？","Mike: Cậu có biết người Trung Quốc thích con số nào không?"],["爱德华：不知道。","Edward: Không biết."],["麦克：你怎么连这么简单的问题也不知道？不过，不知道也好。","Mike: Sao đến câu hỏi đơn giản thế này mà cậu cũng không biết? Nhưng không biết cũng tốt."],["爱德华：什么话！","Edward: Nói gì vậy!"],["麦克：以后你什么问题不知道就来问我好了。","Mike: Sau này có câu hỏi gì không biết thì cứ đến hỏi mình là được."],["爱德华：你知道？","Edward: Cậu biết à?"],["麦克：知道。世界上的事我知道一半儿，中国的事我没有不知道的。","Mike: Biết chứ. Chuyện trên thế giới mình biết một nửa, chuyện Trung Quốc thì không có gì mình không biết."],["爱德华：是吗？","Edward: Thật không?"],["麦克：你没听见大家都叫我什么吗？","Mike: Cậu không nghe mọi người gọi mình là gì à?"],["爱德华：叫你什么？","Edward: Gọi cậu là gì?"],["麦克：“中国通”。","Mike: “Người thông thạo Trung Quốc”."],["爱德华：你才学了三个半月的汉语，怎么就成“中国通”了？","Edward: Cậu mới học tiếng Hán có ba tháng rưỡi, sao đã thành “người thông thạo Trung Quốc” rồi?"],["麦克：这不是说相声吗？你怎么连这也不懂？","Mike: Đây chẳng phải đang diễn tấu hài sao? Sao đến cái này cậu cũng không hiểu?"],["爱德华：谁说我不懂？相声是笑的艺术。说相声就是要大家笑，“笑一笑，十年少”嘛。","Edward: Ai bảo mình không hiểu? Tấu hài là nghệ thuật gây cười. Diễn tấu hài là để mọi người cười, “cười một cái, trẻ ra mười tuổi” mà."],["麦克：对呀。谁听了我们的相声，谁就会笑起来，谁就会变年轻，今年二十，明年十岁。","Mike: Đúng thế. Ai nghe tấu hài của chúng mình thì người đó sẽ bật cười, người đó sẽ trẻ ra, năm nay hai mươi, sang năm mười tuổi."],["爱德华：什么？","Edward: Cái gì?"],["麦克：你不是说“笑一笑，十年少”吗？","Mike: Chẳng phải cậu nói “cười một cái, trẻ ra mười tuổi” sao?"],["爱德华：别开玩笑了。你还是说说中国人喜欢什么数字吧。","Edward: Đừng đùa nữa. Cậu nói xem người Trung Quốc thích con số nào đi."],["麦克：我告诉你，你可别告诉别人。这是我的伟大发现，我正准备去申请专利呢。","Mike: Mình nói cho cậu biết, cậu đừng nói với ai đấy. Đây là phát hiện vĩ đại của mình, mình đang chuẩn bị đi đăng ký bằng sáng chế đấy."],["爱德华：你快说吧，我不会告诉别人的。","Edward: Cậu nói nhanh lên, mình sẽ không nói với ai đâu."],["麦克：中国人最喜欢的数字是“八”。","Mike: Con số người Trung Quốc thích nhất là “tám”."],["爱德华：八？为什么喜欢“八”？","Edward: Tám? Sao lại thích “tám”?"],["麦克：中国人认为这个数字最吉利。","Mike: Người Trung Quốc cho rằng con số này may mắn nhất."],["爱德华：“八”怎么吉利呢？","Edward: “Tám” may mắn ở chỗ nào?"],["麦克：你听！我说“八、八、八”……你能听出什么音来吗？","Mike: Cậu nghe này! Mình nói “bā, bā, bā”… cậu có nghe ra âm gì không?"],["爱德华：“八、八、八”呀！","Edward: Thì “bā, bā, bā” chứ gì!"],["麦克：你真笨啊！连这都听不出来。“八”的谐音不是“发”吗？“八、八、八”就是“发、发、发”呀。","Mike: Cậu ngốc thật! Đến cái này cũng không nghe ra. Âm của “bā” (tám) chẳng phải gần với “fā” (phát) sao? “Tám, tám, tám” chính là “phát, phát, phát” đấy."],["爱德华：我怎么听不出来呢？","Edward: Sao mình không nghe ra nhỉ?"],["麦克：你的汉语水平太低。汉语的“发”是什么意思你知道不？","Mike: Trình độ tiếng Hán của cậu thấp quá. Chữ “phát” trong tiếng Hán nghĩa là gì cậu biết không?"],["爱德华：不知道。","Edward: Không biết."],["麦克：“发”就是“发财”。现在谁不想发财呀？发了财就可以买房子，买汽车，买巧克力，买土豆儿……想买什么就买什么。","Mike: “Phát” chính là “phát tài”. Bây giờ ai mà không muốn phát tài? Phát tài rồi thì có thể mua nhà, mua ô tô, mua sô-cô-la, mua khoai tây… muốn mua gì thì mua nấy."],["爱德华：你胡说什么呀！","Edward: Cậu nói linh tinh gì thế!"],["麦克：只要有钱就能买好多好东西。","Mike: Chỉ cần có tiền là có thể mua được nhiều thứ tốt."],["爱德华：我想起来了。我学过，中国人喜欢“518”这个数，也喜欢“五月十八号”这一天，因为“518”的谐音是“我要发”。","Edward: Mình nhớ ra rồi. Mình học rồi, người Trung Quốc thích số “518”, cũng thích ngày “mười tám tháng năm”, vì “518” đọc gần giống “wǒ yào fā” – “tôi sẽ phát tài”."],["麦克：对！对！怎么？你也知道啊！","Mike: Đúng! Đúng! Sao? Cậu cũng biết à!"],["爱德华：是啊，我还知道中国人也喜欢“六”和“九”。","Edward: Ừ, mình còn biết người Trung Quốc cũng thích số “sáu” và “chín”."],["麦克：为什么？","Mike: Tại sao?"],["爱德华：因为……哎，你不是“中国通”吗？怎么又问起我来了？","Edward: Vì… ơ, chẳng phải cậu là “người thông thạo Trung Quốc” sao? Sao lại quay ra hỏi mình?"],["麦克：我问你，你告诉我，我懂了不就“通”了吗？","Mike: Mình hỏi cậu, cậu nói cho mình, mình hiểu rồi thì chẳng phải là “thông” rồi sao?"],["爱德华：“九”与“长久”的“久”谐音。谁不希望友谊长久，爱情长久，活得长久啊？中国人还常说“六六大顺”。所以我知道中国人也喜欢“六”和“九”。","Edward: “Chín” (jiǔ) đồng âm với chữ “cửu” trong “trường cửu” (lâu dài). Ai mà không mong tình bạn lâu dài, tình yêu lâu dài, sống lâu dài chứ? Người Trung Quốc còn hay nói “lục lục đại thuận” (mọi sự thuận lợi). Vì thế mình biết người Trung Quốc cũng thích “sáu” và “chín”."],["麦克：你不笨啊！","Mike: Cậu không ngốc nhỉ!"],["爱德华：你才笨呢！","Edward: Cậu mới ngốc ấy!"]]},{"zh":"（二）宴会上的规矩","vi":"Phép tắc trong bữa tiệc","phu":false,"pairs":[["麦克：中国人在宴会上的规矩可多了。","Mike: Phép tắc của người Trung Quốc trong bữa tiệc nhiều lắm đấy."],["爱德华：都有什么规矩？","Edward: Có những phép tắc gì?"],["麦克：首先，要请重要的客人、老师、领导和长辈坐上座。","Mike: Trước tiên, phải mời khách quan trọng, thầy cô, lãnh đạo và bậc bề trên ngồi ghế trên."],["爱德华：这是应该的。","Edward: Điều này là đương nhiên."],["麦克：上菜时，如果是鱼的话，鱼头要对着上座，让重要的客人先吃第一口。喝酒的时候，大家都要先给他敬酒。","Mike: Khi dọn món, nếu là cá thì đầu cá phải hướng về ghế trên, để khách quan trọng ăn miếng đầu tiên. Khi uống rượu, mọi người đều phải mời người đó trước."],["爱德华：上次我参加了一个中国朋友的婚礼，大家都让我先吃。是不是也把我看成重要的客人了？","Edward: Lần trước mình dự đám cưới một người bạn Trung Quốc, mọi người đều mời mình ăn trước. Có phải họ cũng coi mình là khách quan trọng không?"],["麦克：是。要是你到中国人家里去做客，他们就会准备好多菜，让你怎么也吃不完。给你敬酒的时候，一定要干杯，把杯子里的酒一口喝光。","Mike: Đúng vậy. Nếu cậu đến nhà người Trung Quốc làm khách, họ sẽ chuẩn bị rất nhiều món, để cậu ăn thế nào cũng không hết. Khi họ mời rượu cậu, nhất định phải cạn ly, uống một hơi hết rượu trong ly."],["爱德华：要是不会喝酒怎么办呢？","Edward: Nếu không biết uống rượu thì làm sao?"],["麦克：那也没关系。他们会说“感情有，茶当酒”。你用茶代替就行了。","Mike: Thế cũng không sao. Họ sẽ nói “có tình cảm thì trà thay rượu”. Cậu dùng trà thay là được."],["爱德华：你怎么知道得这么多啊！","Edward: Sao cậu biết nhiều thế!"],["麦克：“中国通”嘛，当然知道得比你多了。","Mike: “Người thông thạo Trung Quốc” mà, đương nhiên biết nhiều hơn cậu rồi."],["爱德华：哈哈！又吹起来了。","Edward: Ha ha! Lại bắt đầu khoác lác rồi."]]},{"zh":"（综合填空）哪个数字最吉利","vi":"Số nào may mắn nhất","phu":true,"pairs":[["看到很多朋友买了汽车，李四也买了一辆。去办理牌照的时候，工作人员对他说，如果多交100块钱，车牌的最后一个号码可以随便挑。李四就多交了100块钱。工作人员说：“从0到3，从5到9，您选哪个数字呀？”李四说：“我自己决定不了，让我跟妻子商量商量，一会儿我再来告诉您。”工作人员笑着说：“您快点儿啊。”李四说一会儿就来。","Thấy nhiều bạn bè mua ô tô, Lý Tứ cũng mua một chiếc. Lúc đi làm biển số, nhân viên nói với anh ấy, nếu nộp thêm 100 tệ thì số cuối cùng của biển số có thể tùy ý chọn. Lý Tứ liền nộp thêm 100 tệ. Nhân viên nói: “Từ 0 đến 3, từ 5 đến 9, anh chọn số nào?” Lý Tứ nói: “Tôi tự quyết không được, để tôi bàn với vợ đã, lát nữa tôi quay lại báo anh.” Nhân viên cười nói: “Anh nhanh lên nhé.” Lý Tứ nói lát nữa sẽ quay lại ngay."],["李四回到家，对妻子讲了挑号码的事。妻子说：“就挑8嘛，还跟我商量什么？这几年只要带8的东西都卖得快，这个数字最吉利。”李四说：“8跟伤疤的‘疤’同音，不太好。我看6比较合适，六六大顺，你看行不行？”","Lý Tứ về nhà kể với vợ chuyện chọn số. Vợ nói: “Thì chọn số 8 chứ sao, còn bàn với em làm gì? Mấy năm nay cứ thứ gì có số 8 là bán chạy, số này may mắn nhất.” Lý Tứ nói: “Số 8 đồng âm với chữ ‘sẹo’ trong ‘vết sẹo’, không hay lắm. Anh thấy số 6 hợp hơn, ‘lục lục đại thuận’, em thấy được không?”"],["妻子说：“6和‘流’谐音，流氓、流浪，多难听。我看9这个数不错，你说呢？”李四说：“9好什么？九泉，人一死就说去了九泉。9又和‘救’谐音，救济、救命，都是不吉利的词。还是5吧，你看5怎么样？”","Vợ nói: “Số 6 đồng âm với chữ ‘lưu’, lưu manh, lưu lạc, nghe khó chịu quá. Em thấy số 9 được đấy, anh thấy sao?” Lý Tứ nói: “Số 9 hay gì chứ? Cửu tuyền, người ta chết thì bảo là về chín suối. Số 9 lại đồng âm với chữ ‘cứu’, cứu tế, cứu mạng, toàn từ không may mắn. Thôi chọn số 5 đi, em thấy số 5 thế nào?”"],["妻子说：“5更不好了！要是倒数第二位是2、7、8的话，你念念，不就成了‘儿无、妻无、爸无’了吗？另外，5与污染的‘污’谐音，不干净。不能要5，还是7这个数合适。”李四说：“7和‘凄惨’的‘凄’同音，也不好。”","Vợ nói: “Số 5 còn tệ hơn! Nếu số áp chót là 2, 7, 8 thì anh đọc thử xem, chẳng phải thành ‘không con, không vợ, không bố’ sao? Hơn nữa, số 5 đồng âm với chữ ‘ô’ trong ‘ô nhiễm’, không sạch sẽ. Không lấy số 5 được, số 7 mới hợp.” Lý Tứ nói: “Số 7 đồng âm với chữ ‘thê’ trong ‘thê thảm’, cũng không hay.”"],["妻子说：“选3行不行？”李四摇摇头说：“3就是散，就是离婚，多不吉利呀！你想想2可以不可以？”妻子分析说：“二流子、二百五，都和2有关。2和‘儿’谐音，当儿子有低人一等的感觉。不行，不行。”李四说：“那就选1吧。”妻子说：“你怎么糊涂了？1是什么好数字呀？一团糟、一场空，1的贬义词太多。”","Vợ nói: “Chọn số 3 được không?” Lý Tứ lắc đầu nói: “Số 3 là ‘tan’, là ly hôn, xui xẻo biết bao! Em nghĩ xem số 2 có được không?” Vợ phân tích: “Kẻ lêu lổng, đồ ngốc nghếch đều liên quan đến số 2. Số 2 đồng âm với ‘nhi’ (con), làm con thì có cảm giác thấp kém hơn người. Không được, không được.” Lý Tứ nói: “Vậy chọn số 1 đi.” Vợ nói: “Anh lú lẫn rồi à? Số 1 thì hay ho gì? Rối tinh rối mù, công cốc, số 1 có quá nhiều từ mang nghĩa xấu.”"],["李四说：“没关系，在车牌号中人们不说一，说幺。”妻子说：“那就更不好了，‘幺’和‘夭’同音，夭折不就是死了吗？这个更不行了。”李四说：“那就选0吧，0怎么看都是0，永远不会看错。”妻子说：“0和‘灵’同音，灵堂、灵车，都和死人有关系，最不吉利了。”","Lý Tứ nói: “Không sao, trong biển số xe người ta không đọc là ‘yī’ mà đọc là ‘yāo’.” Vợ nói: “Thế lại càng tệ, ‘yāo’ đồng âm với ‘yểu’, chết yểu chẳng phải là chết sao? Cái này càng không được.” Lý Tứ nói: “Vậy chọn số 0 đi, số 0 nhìn kiểu gì cũng là 0, không bao giờ nhìn nhầm.” Vợ nói: “Số 0 đồng âm với ‘linh’, linh đường, xe tang, đều liên quan đến người chết, xui xẻo nhất.”"],["李四说：“那就只有4了，我认为这个数字不坏，四季发财，我李四从小到大，平安无事地长这么大，就是和‘4’有关系。”妻子说：“别说了，4就是死，谁不知道这是个倒霉的数字？我们要选这个数，人家会笑掉牙的。”","Lý Tứ nói: “Vậy chỉ còn số 4, anh thấy số này không tệ, bốn mùa phát tài, anh Lý Tứ từ bé đến lớn bình an vô sự lớn chừng này, chính là nhờ có liên quan đến số ‘4’.” Vợ nói: “Thôi đừng nói nữa, số 4 là ‘tử’ (chết), ai mà chẳng biết đây là con số xui xẻo? Mình mà chọn số này, người ta cười rụng răng mất.”"],["李四说：“0到9我们都研究过了，都不行，你说怎么办？”妻子说：“从0到9，每张纸上各写一个数字，揉成纸团，抓到哪个是哪个吧。”李四说：“这个办法不错。”妻子写好10个数字，把纸团放在一起，随便抓了一个，打开一看……妻子伤心地哭了起来。","Lý Tứ nói: “Từ 0 đến 9 mình xem hết rồi, số nào cũng không được, em bảo phải làm sao?” Vợ nói: “Từ 0 đến 9, mỗi tờ giấy viết một số, vo thành viên giấy, bốc được số nào thì lấy số đó.” Lý Tứ nói: “Cách này hay đấy.” Vợ viết xong 10 con số, để các viên giấy cùng một chỗ, bốc đại một viên, mở ra xem… Người vợ đau lòng khóc òa lên."],["李四又来到办牌照的窗口前，把纸上的数字给工作人员看了一下儿，说：“就要这个数。”工作人员办完手续后又把100块钱还给了李四。李四问：“这100块钱怎么又还给我了？”工作人员说：“你选的这个数不加钱。”","Lý Tứ lại đến trước quầy làm biển số, đưa con số trên tờ giấy cho nhân viên xem, nói: “Lấy số này.” Nhân viên làm xong thủ tục lại trả 100 tệ cho Lý Tứ. Lý Tứ hỏi: “Sao lại trả tôi 100 tệ này?” Nhân viên nói: “Số anh chọn không phải trả thêm tiền.” (Ý: bốc trúng số 4 – số không ai muốn chọn.)"]]}],"grammar":[{"title":"连…也 / 都… — ngay cả… cũng…","f":["连 + Thành phần nhấn mạnh + 也 / 都 + Động từ","Câu khẳng định thường dùng 都, phủ định dùng 也 hoặc 都"],"note":"Nêu một trường hợp cực đoan (dễ nhất / khó nhất) để nhấn mạnh. Thành phần sau 连 có thể là chủ ngữ, tân ngữ hoặc động từ.","ex":[["她连长城也没去过。","Ngay cả Trường Thành cô ấy cũng chưa đi."],["你怎么连这么简单的问题也不知道？","Sao ngay cả câu đơn giản vậy bạn cũng không biết?"],["我连这本书的名字都没听说过。","Đến tên quyển sách này tôi còn chưa nghe."],["连校长都参加了。","Ngay cả hiệu trưởng cũng tham gia."],["他忙得常常连星期日也不能休息。","Anh ấy bận đến mức chủ nhật cũng thường không được nghỉ."]],"warn":[]},{"title":"Câu hỏi ngược (反问句)","f":["不是 … 吗？ — chẳng phải … sao? (= khẳng định)","没 + V + 吗？ — chưa … à? (= lẽ ra đã …)","怎么 / 哪儿 / 谁 + … ？ — sao mà…, đâu có…, ai mà… (= phủ định)","怎么能不 … 呢？ — sao lại không … được? (= phải …)"],"note":"Hình thức là câu hỏi nhưng không cần trả lời, dùng để nhấn mạnh. Có phủ định thì ý khẳng định, không phủ định thì ý phủ định.","ex":[["“八”的谐音不是“发”吗？","Chữ “tám” chẳng phải đồng âm với “phát” sao?"],["这件事你没听说过吗？","Chuyện này bạn chưa nghe à? (= Lẽ ra phải nghe rồi.)"],["我怎么知道呢？","Làm sao tôi biết được? (= Tôi không biết.)"],["他哪儿去过美国？","Anh ấy đi Mỹ bao giờ đâu? (= Chưa đi.)"],["谁说我不懂？","Ai bảo tôi không hiểu? (= Tôi hiểu.)"],["好朋友邀请我，我怎么能不去呢？","Bạn thân mời, sao tôi không đi được? (= Phải đi.)"],["现在谁不想发财呀？","Bây giờ ai mà không muốn phát tài? (= Ai cũng muốn.)"]],"warn":[]},{"title":"Phủ định kép (二次否定) — khẳng định mạnh","f":["没有 + (Danh từ) + 不 + V + 的 — không có … nào không …","不能不 + V / 不会不 + V — không thể không = phải"],"note":"Hai lần phủ định thành khẳng định, ý mạnh hơn câu khẳng định thường.","ex":[["中国的事我没有不知道的。","Chuyện Trung Quốc không có gì tôi không biết."],["明天考试，你不能不去。","Mai thi, bạn không thể không đi. (= Phải đi.)"],["他答应了，不会不来的。","Anh ấy đã hứa rồi, không thể không đến đâu."]],"warn":[]},{"title":"Cách nói trong bài: 什么话！ · …好了 · 谁…谁…","f":["什么话！ — nói gì kỳ vậy! (phản đối, không hài lòng)","… 好了 — cứ … đi (đồng ý, cho phép)","谁 … 谁就 … — ai … thì người đó … (hô ứng, xem bài 23)","的 + Danh từ: 我的书 · 漂亮的衣服","地 + Động từ: 认真地学习 · 一步一步地走","Động từ / Tính từ + 得: 说得很好 · 高兴得跳起来"],"note":"Mấy cách nói khẩu ngữ trong bài tướng thanh, hay ra ở phần dịch và điền từ.","ex":[["— 不知道也好。— 什么话！","— Không biết cũng tốt. — Nói gì kỳ vậy!"],["你什么问题不知道就来问我好了。","Bạn có gì không biết cứ đến hỏi tôi."],["谁听了我们的相声，谁就会笑起来。","Ai nghe tướng thanh của bọn tôi thì người đó sẽ bật cười."]],"warn":[]},{"title":"Phân biệt nhanh 的 · 地 · 得","f":["的 + Danh từ: 我的书 · 漂亮的衣服","地 + Động từ: 认真地学习 · 一步一步地走","Động từ / Tính từ + 得: 说得很好 · 高兴得跳起来"],"note":"Nhìn chữ ngay SAU chỗ trống: danh từ → 的; động từ → 地. Nhìn chữ ngay TRƯỚC: động từ/tính từ rồi tới phần miêu tả mức độ/kết quả → 得.","ex":[["他们一步一步地往上爬。","Họ từng bước từng bước leo lên."],["她高兴得跳了起来。","Cô ấy vui đến mức nhảy cẫng lên."],["这一幅一幅的画儿都是她送给我的。","Những bức tranh này đều là cô ấy tặng tôi."]],"warn":[]}]}]});
